import { deleteCatalogEntitySafely, deleteRow, finalizeProductRelations, getAdminProducts, getBrands, getCatalogEntityDependencies, getCategories, getDeliveryMethods, getHomepageBanners, getPaymentMethods, getSettings, prepareProductRelations, removeCatalogEntityAsset, removePaymentMethodAsset, saveRow, saveSettings, supabase, syncProductImages, uploadImage } from '../lib/api.js';
import { configureCrm, invalidateCrmSettings, renderCustomers, renderDashboard, renderOrders, renderQuotes, renderSales } from './admin-crm.js';
import { mountBannerEditor } from '../components/banner-editor.js';
import { chooseAction, confirmAction, openModal } from '../components/modal.js';
import { toast } from '../components/toast.js';
import { $, $$, categoryInitials, currentPrice, escapeHtml, formatMoney, getPromotionStatus, isPromoActive, localAsset, normalizeText, paymentInitials, setButtonLoading, slugify } from '../lib/helpers.js';
import { ANNOUNCEMENT_INTERVAL_MAX, ANNOUNCEMENT_INTERVAL_MIN, ANNOUNCEMENT_TEXT_LIMIT, announcementValues, createAnnouncementController, normalizeAnnouncementSettings, validateAnnouncement } from '../lib/announcement.js';
import { formatBytes, imageFingerprint, imageProcessingMessage, IMAGE_LIMITS, prepareProductImage } from '../lib/image-processor.js';

let products=[];let categories=[];let brands=[];let adminSession=null;
let activeSection='dashboard';
let activeSectionCleanup=()=>{};
const PAGE_SIZE=20;
const STOCK_PAGE_SIZE=30;
const ENTITY_PAGE_SIZE=30;
const cleanText=normalizeText;
const debounce=(callback,delay=200)=>{let timer;return(...args)=>{clearTimeout(timer);timer=setTimeout(()=>callback(...args),delay);};};
const productImage=product=>localAsset(product.product_images?.find(image=>image.is_primary)?.url||product.product_images?.[0]?.url);
const totalStock=product=>product.product_variants.reduce((sum,variant)=>sum+Number(variant.stock||0),0);
const isProductSoldOut=product=>product.force_sold_out||totalStock(product)===0;
const lowThreshold=product=>Number(product?.low_stock_threshold??3);
const isProductLow=product=>product.force_last_units||isProductSoldOut(product)||product.product_variants.some(variant=>variant.active!==false&&variant.stock>0&&variant.stock<=lowThreshold(product));
const stockStatus=(stock,product=null)=>product?.force_sold_out||stock===0?{label:'Agotado',className:'sold'}:product?.force_last_units||stock<=lowThreshold(product)?{label:'Últimas unidades',className:'low'}:{label:'Disponible',className:'available'};

export async function initAdmin(){
  const{data:{session}}=await supabase.auth.getSession();
  if(!session){location.replace('login.html');return;}
  const{data:admin}=await supabase.from('admins').select('user_id').eq('user_id',session.user.id).maybeSingle();
  if(!admin){await supabase.auth.signOut();location.replace('login.html');return;}
  adminSession=session;
  $('#logout-button').addEventListener('click',async()=>{await supabase.auth.signOut();location.replace('login.html');});
  setupDrawer();setupActionMenus();
  configureCrm({heading,navigateTo,getProducts:()=>products,getCategories:()=>categories,isProductLow,refreshProducts:refreshData});
  $('#admin-nav').addEventListener('click',event=>{const button=event.target.closest('[data-section]');if(!button)return;closeDrawer();navigateTo(button.dataset.section);});
  window.addEventListener('popstate',()=>loadSection(new URLSearchParams(location.search).get('section')||'dashboard'));
  await refreshData();await loadSection(new URLSearchParams(location.search).get('section')||'dashboard');
}

function setupActionMenus(){
  document.addEventListener('click',event=>{$$('.action-menu[open]').forEach(menu=>{if(!menu.contains(event.target))menu.open=false;});});
  document.addEventListener('toggle',event=>{const menu=event.target.closest?.('.action-menu');if(!menu)return;const summary=menu.querySelector('summary');summary?.setAttribute('aria-expanded',String(menu.open));if(menu.open){$$('.action-menu[open]').filter(item=>item!==menu).forEach(item=>item.open=false);const rect=menu.getBoundingClientRect();const popover=menu.querySelector('.action-menu__popover');menu.classList.toggle('action-menu--up',Boolean(popover&&innerHeight-rect.bottom<Math.min(220,popover.scrollHeight+16)&&rect.top>popover.scrollHeight));}else menu.classList.remove('action-menu--up');},true);
  document.addEventListener('keydown',event=>{if(event.key!=='Escape')return;const menu=document.querySelector('.action-menu[open]');if(!menu)return;event.preventDefault();menu.open=false;menu.querySelector('summary')?.focus();});
}

function setupDrawer(){
  const sidebar=$('#admin-sidebar');const backdrop=$('#admin-sidebar-backdrop');const menu=$('#admin-menu');const close=$('#admin-menu-close');
  menu.addEventListener('click',()=>{sidebar.classList.add('open');backdrop.hidden=false;requestAnimationFrame(()=>backdrop.classList.add('visible'));document.body.classList.add('no-scroll');menu.setAttribute('aria-expanded','true');close.focus();});
  close.addEventListener('click',closeDrawer);backdrop.addEventListener('click',closeDrawer);
  matchMedia('(min-width: 900px)').addEventListener('change',event=>{if(event.matches)closeDrawer();});
  document.addEventListener('keydown',event=>{if(!sidebar.classList.contains('open'))return;if(event.key==='Escape'){event.preventDefault();closeDrawer();return;}if(event.key!=='Tab')return;const focusable=[...sidebar.querySelectorAll('a[href],button:not([disabled])')];const first=focusable[0];const last=focusable.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}});
}

function closeDrawer(){
  const sidebar=$('#admin-sidebar');const backdrop=$('#admin-sidebar-backdrop');const menu=$('#admin-menu');if(!sidebar?.classList.contains('open'))return;
  sidebar.classList.remove('open');backdrop.classList.remove('visible');document.body.classList.remove('no-scroll');menu.setAttribute('aria-expanded','false');setTimeout(()=>{if(!sidebar.classList.contains('open'))backdrop.hidden=true;},210);menu.focus({preventScroll:true});
}

function navigateTo(section,params={}){
  const query=new URLSearchParams({section,...Object.fromEntries(Object.entries(params).filter(([,value])=>value!==''&&value!=null))});
  history.pushState({},'',`${location.pathname}?${query}`);loadSection(section);window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});
}

async function refreshData(){[products,categories,brands]=await Promise.all([getAdminProducts(),getCategories({all:true}),getBrands({all:true})]);}

async function loadSection(section){
  if(!['dashboard','orders','customers','quotes','sales','products','stock','categories','brands','promotions','settings'].includes(section))section='dashboard';
  activeSectionCleanup();activeSectionCleanup=()=>{};
  activeSection=section;$$('#admin-nav button').forEach(button=>button.classList.toggle('active',button.dataset.section===section));
  const root=$('#admin-content');root.innerHTML=['categories','brands'].includes(section)?entityLoadingMarkup():'<div class="admin-loading"><span class="spinner"></span> Cargando…</div>';
  const loaders={dashboard:renderDashboard,orders:renderOrders,customers:renderCustomers,quotes:renderQuotes,sales:renderSales,products:renderProducts,stock:renderStock,categories:()=>renderEntities('categories'),brands:()=>renderEntities('brands'),promotions:renderPromotions,settings:renderSettings};
  try{await loaders[section]?.();}catch(error){console.error(error);root.innerHTML='<div class="empty-state"><h1>No pudimos cargar esta sección</h1><p>Intenta nuevamente.</p></div>';}
}

function heading(kicker,title,text,button=''){return `<header class="admin-heading"><div><span class="eyebrow">${kicker}</span><h1>${title}</h1>${text?`<p>${text}</p>`:''}</div>${button}</header>`;}

function categoryPath(category){
  const path=[];let current=category;const visited=new Set();
  while(current&&!visited.has(current.id)){visited.add(current.id);path.unshift(current.name);current=categories.find(item=>item.id===current.parent_id);}
  return path.join(' › ');
}

function categorySelectorMarkup(product){
  const selected=new Set((product?.product_categories||[]).map(row=>row.category_id));
  const childrenOf=id=>categories.filter(item=>item.parent_id===id);
  const descendantsOf=id=>childrenOf(id).flatMap(child=>[child,...descendantsOf(child.id)]);
  const roots=categories.filter(item=>!item.parent_id||!categories.some(parent=>parent.id===item.parent_id));
  const hasSelectedDescendant=id=>childrenOf(id).some(child=>selected.has(child.id)||hasSelectedDescendant(child.id));
  const node=(category,depth=0)=>{
    const children=childrenOf(category.id);const expanded=children.length&&hasSelectedDescendant(category.id);
    const searchText=cleanText([category.name,...descendantsOf(category.id).map(child=>categoryPath(child))].join(' '));
    return `<div class="product-category-node" data-category-node data-category-id="${category.id}" data-category-name="${escapeHtml(cleanText(category.name))}" data-category-search="${escapeHtml(searchText)}">
      <div class="product-category-row" style="--category-depth:${depth}">
        <label><input type="checkbox" name="categoryIds" value="${category.id}" ${selected.has(category.id)?'checked':''}><span>${escapeHtml(category.name)}</span></label>
        ${children.length?`<button class="product-category-toggle" data-category-toggle="${category.id}" type="button" aria-expanded="${expanded?'true':'false'}" aria-controls="category-children-${category.id}" aria-label="${expanded?'Contraer':'Desplegar'} subcategorías de ${escapeHtml(category.name)}"><span aria-hidden="true">›</span></button>`:'<span class="product-category-toggle-spacer" aria-hidden="true"></span>'}
      </div>
      ${children.length?`<div class="product-category-children" id="category-children-${category.id}" data-category-children="${category.id}" ${expanded?'':'hidden'}>${children.map(child=>node(child,depth+1)).join('')}</div>`:''}
    </div>`;
  };
  return `<div class="product-category-selector">
    <div class="product-category-tools"><label class="product-category-search"><span>Buscar</span><input type="search" data-category-search-input placeholder="Buscar categoría o subcategoría..." autocomplete="off"></label><p data-category-count aria-live="polite"></p></div>
    <div class="product-category-chips" data-category-chips aria-label="Categorías seleccionadas"></div>
    <div class="product-category-tree" data-category-tree>${roots.map(category=>node(category)).join('')}</div>
    <p class="product-category-empty" data-category-empty hidden>No hay categorías que coincidan con la búsqueda.</p>
  </div>`;
}

// Especificaciones técnicas flexibles: se guardan como {items:[{label,value}]} para conservar el orden.
function specificationItems(value){return Array.isArray(value?.items)?value.items.filter(item=>item?.label&&item?.value):[];}
function specificationRow(item={}){return `<div class="dynamic-row spec-row" data-spec-row><label>Característica<input data-spec-label maxlength="80" value="${escapeHtml(item.label||'')}" placeholder="Ej. Capacidad"></label><label>Valor<input data-spec-value maxlength="200" value="${escapeHtml(item.value||'')}" placeholder="Ej. 300 litros"></label><button data-remove-spec type="button" aria-label="Quitar característica">×</button></div>`;}

function productPreviewMarkup(product){
  const text=value=>escapeHtml(String(value||'').trim()).replace(/\r?\n/g,'<br>');
  const information=[];
  if(product.description)information.push(`<section><h4>Detalles del producto</h4><p>${text(product.description)}</p></section>`);
  const specs=specificationItems(product.specifications);
  if(specs.length)information.push(`<section><h4>Especificaciones</h4><dl>${specs.map(item=>`<dt>${text(item.label)}</dt><dd>${text(item.value)}</dd>`).join('')}</dl></section>`);
  if(product.material||product.care_instructions)information.push(`<section><h4>Uso y cuidado</h4>${product.material?`<p><strong>Materiales:</strong><br>${text(product.material)}</p>`:''}${product.care_instructions?`<p>${text(product.care_instructions)}</p>`:''}</section>`);
  if(product.purchase_delivery_info)information.push(`<section><h4>Compra y entrega</h4><p>${text(product.purchase_delivery_info)}</p></section>`);
  return `<article class="admin-product-preview"><div class="admin-product-preview__summary"><div class="product-card__media"><img src="${escapeHtml(product.preview_image||'../assets/images/product-white.svg')}" alt="Vista previa"></div><div><small>${escapeHtml(brands.find(brand=>brand.id===product.brand_id)?.name||'Bodega Mayorista F.C.')}</small><h3>${escapeHtml(product.name||'Producto sin nombre')}</h3><div class="price"><strong>${formatMoney(product.promo_price??product.base_price)}</strong>${product.promo_price!=null?`<del>${formatMoney(product.base_price)}</del>`:''}</div></div></div>${information.length?`<div class="admin-product-preview__information">${information.join('')}</div>`:'<p class="admin-product-preview__empty">Este producto no tiene información adicional para mostrar.</p>'}</article>`;
}

function openProductForm(product=null){
  const makeKey=prefix=>`${prefix}-${crypto.randomUUID()}`;
  const colorItems=(product?.product_colors?.length?product.product_colors:[{name:'Única',hex_code:null}]).slice().sort((a,b)=>a.sort_order-b.sort_order).map(item=>({...item,clientId:item.id||makeKey('color')}));
  const sizeItems=(product?.product_sizes?.length?product.product_sizes:[{name:'Única'}]).slice().sort((a,b)=>a.sort_order-b.sort_order).map(item=>({...item,clientId:item.id||makeKey('size')}));
  const colorKeyForId=id=>colorItems.find(item=>item.id===id)?.clientId||'';
  const imageItems=(product?.product_images||[]).slice().sort((a,b)=>a.sort_order-b.sort_order).map((item,index)=>({...item,url:localAsset(item.url),clientId:`image-${item.id}`,colorKey:colorKeyForId(item.color_id),name:item.alt_text||`Fotografía ${index+1}`,isPrimary:Boolean(item.is_primary),sortOrder:Number(item.sort_order??index),status:'loaded',deleted:false}));
  const stockMap=new Map((product?.product_variants||[]).map(variant=>{const color=colorItems.find(item=>item.id===variant.color_id);const size=sizeItems.find(item=>item.id===variant.size_id);return[color&&size?`${color.clientId}|${size.clientId}`:'',variant.stock];}).filter(([key])=>key));
  let activePhotoKey='';let savedProductId=product?.id||null;let processingQueue=Promise.resolve();let editorClosed=false;let formSaving=false;
  const form=document.createElement('form');form.className='admin-form product-editor';form.noValidate=true;form.innerHTML=productFormMarkup(product);
  const sections=[...form.querySelectorAll(':scope > .admin-form__section')];const photoSection=sections[2];const optionSection=sections[3];
  optionSection.innerHTML=`<div class="admin-form__section-head"><span>3</span><div><h3>Opciones y variantes</h3><p>Si el producto no tiene opciones (por ejemplo, una nevera de un solo modelo), deja “Única” en ambas listas: la tienda no mostrará selectores. Si las tiene, nómbralas (color, capacidad, almacenamiento, voltaje, presentación, modelo compatible…).</p></div></div><div class="form-grid option-names"><label>Nombre de la opción 1 <small>Opcional</small><input name="option1_name" maxlength="40" value="${escapeHtml(product?.option1_name||'')}" placeholder="Ej. Color"></label><label>Nombre de la opción 2 <small>Opcional</small><input name="option2_name" maxlength="40" value="${escapeHtml(product?.option2_name||'')}" placeholder="Ej. Capacidad"></label></div><div class="color-editor"><div class="color-add"><label for="new-color-name" data-option1-label>Valores de opción 1</label><div><input id="new-color-name" type="text" maxlength="80" placeholder="Ejemplo: Negro o 220 V" autocomplete="off"><button id="add-color" class="small-btn small-btn--primary" type="button">Agregar valor</button></div><p id="color-feedback" class="field-message" role="status" aria-live="polite"></p></div><div id="admin-colors" class="color-list" aria-label="Valores de opción 1"></div></div><div class="admin-panel__head product-subsection-head"><strong data-option2-label>Valores de opción 2</strong><button id="add-size" class="small-btn" type="button">+ Valor</button></div><div id="admin-sizes" class="dynamic-list"></div><details class="admin-form-disclosure"><summary>Guía opcional <span aria-hidden="true">⌄</span></summary><div class="admin-form-disclosure__body form-grid"><label class="form-grid__full">Texto de apoyo<textarea name="size_guide_text" rows="3" placeholder="Ej. Tabla de capacidades o compatibilidad">${escapeHtml(product?.size_guide_text||'')}</textarea></label><input name="size_guide_image_url" type="hidden" value="${escapeHtml(product?.size_guide_image_url||'')}"><label class="form-grid__full">Imagen de apoyo <small>Opcional</small><input data-upload="size_guide_image_url" type="file" accept="image/*"></label></div></details>`;
  photoSection.innerHTML=`<div class="admin-form__section-head"><span>4</span><div><h3>Fotografías</h3><p>Sube fotografías generales o elige un valor de la opción 1 (por ejemplo, un color) para asociarle imágenes. Se conserva la orientación y la proporción; las fotos pesadas se optimizan automáticamente.</p></div></div><div id="photo-tabs" class="photo-tabs" role="tablist" aria-label="Destino de las fotografías"></div><p id="photo-empty-colors" class="photo-help">Si el producto tiene valores en la opción 1, puedes asociar fotografías a cada uno.</p><div id="photo-dropzone" class="photo-dropzone"><input id="product-files" class="photo-file-input" type="file" accept="image/jpeg,image/png,image/webp,image/avif,image/heic,image/heif,.heic,.heif" multiple tabindex="-1"><div class="photo-dropzone__content"><strong id="photo-upload-title">Subir fotografías generales</strong><span>Arrastra imágenes aquí o elige varios archivos</span><button id="choose-product-files" class="small-btn small-btn--primary" type="button">Elegir fotografías</button><small>JPG, PNG, WebP, AVIF o HEIC · entrada segura hasta 50 MB</small></div></div><p id="photo-progress" class="photo-progress" role="status" aria-live="polite"></p><p id="photo-feedback" class="field-message" role="status" aria-live="polite"></p><div id="photo-gallery" class="photo-gallery"></div>`;
  photoSection.before(optionSection);
  const revokePreviews=()=>imageItems.forEach(item=>{item.controller?.abort();if(item.objectUrl){URL.revokeObjectURL(item.objectUrl);item.objectUrl='';}});
  const optionName=index=>String(form.elements[`option${index}_name`]?.value||'').trim()||`Opción ${index}`;
  const specsRoot=form.querySelector('[data-specs]');
  const collectSpecs=()=>[...specsRoot.querySelectorAll('[data-spec-row]')].map(row=>({label:row.querySelector('[data-spec-label]').value.trim(),value:row.querySelector('[data-spec-value]').value.trim()})).filter(item=>item.label&&item.value);
  const editorSignature=()=>{collectOptions();return JSON.stringify([collectProductValues(form),colorItems.map(item=>item.name),sizeItems.map(item=>item.name),[...stockMap],imageItems.filter(item=>!item.deleted).map(item=>[item.clientId,item.colorKey,item.isPrimary,item.sortOrder]),[...form.querySelectorAll('[name="categoryIds"]:checked')].map(input=>input.value),collectSpecs(),[...form.querySelectorAll('input[type="file"]')].map(input=>input.files.length)]);};
  let initialSignature='';
  const modal=openModal({title:product?'Editar producto':'Nuevo producto',content:form,className:'modal--product',closeOnBackdrop:false,closeOnEscape:true,beforeClose:async()=>{if(formSaving)return false;if(!initialSignature||editorSignature()===initialSignature)return true;return confirmAction('Tienes cambios sin guardar en este producto. Si cierras ahora se perderán.','Descartar cambios',{confirmLabel:'Descartar cambios',cancelLabel:'Seguir editando'});},onClose:()=>{editorClosed=true;revokePreviews();}});
  const colorsRoot=form.querySelector('#admin-colors');const sizesRoot=form.querySelector('#admin-sizes');const matrix=form.querySelector('#variant-matrix');const formError=form.querySelector('[data-product-form-error]');
  const feedback=(selector,message,error=false)=>{const root=form.querySelector(selector);root.textContent=message;root.classList.toggle('field-message--error',error);};
  const showFormError=(message,target)=>{formError.textContent=message;formError.hidden=false;(target||formError).scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'center'});target?.focus({preventScroll:true});};
  const clearFormError=()=>{formError.hidden=true;formError.textContent='';form.querySelector('[aria-invalid="true"]')?.removeAttribute('aria-invalid');};
  const normalizeName=value=>String(value||'').trim().replace(/\s+/g,' ');
  const duplicateColor=(name,exceptKey='')=>colorItems.some(item=>item.clientId!==exceptKey&&normalizeName(item.name).toLocaleLowerCase('es')===normalizeName(name).toLocaleLowerCase('es'));
  const collectMatrix=()=>matrix.querySelectorAll('[data-stock]').forEach(input=>stockMap.set(`${input.dataset.colorKey}|${input.dataset.sizeKey}`,Math.max(0,Number(input.value)||0)));
  const collectOptions=()=>{colorsRoot.querySelectorAll('[data-color-name]').forEach(input=>{const item=colorItems.find(color=>color.clientId===input.dataset.colorName);if(item)item.name=normalizeName(input.value);});sizesRoot.querySelectorAll('.dynamic-row').forEach(row=>{const item=sizeItems.find(size=>size.clientId===row.dataset.key);if(item)item.name=normalizeName(row.querySelector('input').value);});collectMatrix();};
  const renderMatrix=()=>{if(!colorItems.length||!sizeItems.length){matrix.innerHTML=`<p>${!colorItems.length?'Agrega al menos un valor en la opción 1 (usa “Única” si no aplica).':'Agrega al menos un valor en la opción 2 (usa “Única” si no aplica).'}</p>`;return;}matrix.innerHTML=`<table class="variant-table"><thead><tr><th>${escapeHtml(optionName(1))} / ${escapeHtml(optionName(2))}</th>${sizeItems.map(size=>`<th>${escapeHtml(size.name)}</th>`).join('')}</tr></thead><tbody>${colorItems.map(color=>`<tr><th>${escapeHtml(color.name)}</th>${sizeItems.map(size=>`<td><input type="number" min="0" value="${stockMap.get(`${color.clientId}|${size.clientId}`)||0}" data-stock data-color-key="${color.clientId}" data-size-key="${size.clientId}" aria-label="Stock ${escapeHtml(color.name)} ${escapeHtml(size.name)}"></td>`).join('')}</tr>`).join('')}</tbody></table>`;};
  const renderSizes=()=>{sizesRoot.innerHTML=sizeItems.map(item=>`<div class="dynamic-row" data-key="${item.clientId}" style="grid-template-columns:1fr auto"><label>Valor<input value="${escapeHtml(item.name)}" maxlength="80" required></label><button data-remove-size type="button" aria-label="Quitar valor ${escapeHtml(item.name)}">×</button></div>`).join('');};
  const renderColors=()=>{colorsRoot.innerHTML=colorItems.length?colorItems.map(item=>`<div class="color-item"><label><span class="sr-only">Editar valor ${escapeHtml(item.name)}</span><input data-color-name="${item.clientId}" value="${escapeHtml(item.name)}" maxlength="80" aria-label="Valor ${escapeHtml(item.name)}"></label><button data-remove-color="${item.clientId}" type="button" aria-label="Eliminar valor ${escapeHtml(item.name)}">Eliminar</button></div>`).join(''):'<p class="color-list__empty">Todavía no agregaste valores.</p>';};
  const normalizeImageOrder=()=>imageItems.filter(item=>!item.deleted).forEach((item,index)=>{item.sortOrder=index;});
  const destinationOptions=selected=>`<option value="" ${!selected?'selected':''}>General</option>${colorItems.map(color=>`<option value="${color.clientId}" ${selected===color.clientId?'selected':''}>${escapeHtml(color.name)}</option>`).join('')}`;
  const isProcessing=image=>['preparing','optimizing'].includes(image.status);
  const renderPhotoManager=()=>{
    if(editorClosed)return;
    if(activePhotoKey&&!colorItems.some(color=>color.clientId===activePhotoKey))activePhotoKey='';
    const tabs=[{clientId:'',name:'General'},...colorItems];
    const activeImages=imageItems.filter(item=>!item.deleted);
    const visible=activeImages.filter(item=>item.colorKey===activePhotoKey);
    form.querySelector('#photo-tabs').innerHTML=tabs.map(tab=>{const count=activeImages.filter(item=>item.colorKey===tab.clientId).length;return`<button class="photo-tab ${tab.clientId===activePhotoKey?'active':''}" data-photo-tab="${tab.clientId}" type="button" role="tab" aria-selected="${tab.clientId===activePhotoKey}">${escapeHtml(tab.name)} <span>${count}</span></button>`;}).join('');
    form.querySelector('#photo-empty-colors').hidden=colorItems.length>0;
    const destination=colorItems.find(item=>item.clientId===activePhotoKey)?.name;
    form.querySelector('#photo-upload-title').textContent=destination?`Subir fotografías para ${destination}`:'Subir fotografías generales';
    const statusLabels={preparing:'Preparando…',optimizing:'Optimizando imagen…',ready:'Lista para subir',uploading:'Subiendo imagen…',loaded:'Carga completada',error:'No se pudo completar'};
    form.querySelector('#photo-gallery').innerHTML=visible.length?visible.map((image,index)=>{
      const src=image.objectUrl||image.url||'../assets/images/product-white.svg';
      const busy=isProcessing(image)||image.status==='uploading';
      const detail=image.statusDetail?`<small class="photo-card__detail">${escapeHtml(image.statusDetail)}</small>`:'';
      return`<article class="photo-card ${busy?'photo-card--busy':''}" data-photo="${image.clientId}"><div class="photo-card__media"><img src="${escapeHtml(src)}" alt="Previsualización de ${escapeHtml(image.name)}"><span class="photo-card__destination">${escapeHtml(destination||'General')}</span>${image.isPrimary?'<span class="photo-card__primary">Imagen principal</span>':''}${busy?'<span class="photo-card__spinner spinner" aria-hidden="true"></span>':''}</div><div class="photo-card__body"><strong title="${escapeHtml(image.name)}">${escapeHtml(image.name)}</strong><span class="photo-card__status photo-card__status--${image.status}" role="status">${statusLabels[image.status]||'Pendiente'}</span>${detail}<label>Asignar a<select data-photo-color="${image.clientId}" ${busy?'disabled':''}>${destinationOptions(image.colorKey)}</select></label><div class="photo-card__actions"><button data-photo-move="up" type="button" aria-label="Mover fotografía antes" ${busy||index===0?'disabled':''}>↑</button><button data-photo-move="down" type="button" aria-label="Mover fotografía después" ${busy||index===visible.length-1?'disabled':''}>↓</button><button data-set-primary type="button" ${busy||image.isPrimary?'disabled':''}>${image.isPrimary?'Principal':'Hacer principal'}</button>${image.status==='error'?'<button data-retry-photo type="button">Reintentar</button>':''}<button data-remove-photo type="button">Eliminar</button></div></div></article>`;
    }).join(''):'<div class="photo-gallery__empty"><strong>No hay fotografías en este destino.</strong><span>Usa el área superior para agregar una o varias.</span></div>';
    const processing=activeImages.filter(isProcessing).length;
    const uploading=activeImages.filter(image=>image.status==='uploading').length;
    const errors=activeImages.filter(image=>image.status==='error').length;
    const ready=activeImages.filter(image=>image.status==='ready').length;
    const progress=form.querySelector('#photo-progress');
    progress.classList.toggle('photo-progress--error',errors>0);
    progress.textContent=processing?`Optimizando ${processing} fotografía${processing===1?'':'s'}…`:uploading?`Subiendo ${uploading} fotografía${uploading===1?'':'s'}…`:errors?`${errors} fotografía${errors===1?' necesita':'s necesitan'} atención. Puedes reintentar sin seleccionarla de nuevo.`:ready?`${ready} fotografía${ready===1?' está':'s están'} lista${ready===1?'':'s'} para subir al guardar.`:'';
    form.querySelector('#photo-dropzone').classList.toggle('is-busy',processing>0);
    const submit=form.querySelector('.form-actions [type="submit"]');
    if(submit)submit.disabled=formSaving||processing>0;
  };
  const renderOptionState=()=>{renderColors();renderSizes();renderMatrix();renderPhotoManager();};
  const addColor=()=>{const input=form.querySelector('#new-color-name');const name=normalizeName(input.value);if(!name){input.setAttribute('aria-invalid','true');feedback('#color-feedback','Escribe el valor.',true);input.focus();return;}if(duplicateColor(name)){input.setAttribute('aria-invalid','true');feedback('#color-feedback','Este valor ya existe.',true);input.focus();return;}collectOptions();const item={clientId:makeKey('color'),name};colorItems.push(item);input.value='';input.removeAttribute('aria-invalid');feedback('#color-feedback',`El valor ${name} fue agregado.`);renderOptionState();input.focus();};
  form.querySelector('#add-color').addEventListener('click',addColor);form.querySelector('#new-color-name').addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();addColor();}});
  colorsRoot.addEventListener('input',event=>{const input=event.target.closest('[data-color-name]');if(!input)return;const item=colorItems.find(color=>color.clientId===input.dataset.colorName);item.name=normalizeName(input.value);const duplicate=duplicateColor(item.name,item.clientId);input.toggleAttribute('aria-invalid',!item.name||duplicate);feedback('#color-feedback',!item.name?'El valor no puede estar vacío.':duplicate?'Este valor ya existe.':`El valor ahora es ${item.name}.`,!item.name||duplicate);collectMatrix();renderMatrix();renderPhotoManager();});
  colorsRoot.addEventListener('click',async event=>{const button=event.target.closest('[data-remove-color]');if(!button)return;collectOptions();const key=button.dataset.removeColor;const item=colorItems.find(color=>color.clientId===key);const associated=imageItems.filter(image=>!image.deleted&&image.colorKey===key);let choice='remove';if(associated.length)choice=await chooseAction(`El valor ${item.name} tiene ${associated.length} fotografía${associated.length===1?'':'s'} asociada${associated.length===1?'':'s'}. ¿Qué deseas hacer?`,'Eliminar valor',[{value:'move',label:'Mover fotografías a General',tone:'primary'},{value:'delete',label:'Eliminar valor y sus fotografías',tone:'danger'},{value:null,label:'Cancelar'}],{trigger:button});if(!choice)return;if(choice==='move')associated.forEach(image=>{image.colorKey='';});if(choice==='delete')associated.forEach(image=>{image.deleted=true;image.controller?.abort();if(image.objectUrl)URL.revokeObjectURL(image.objectUrl);image.objectUrl='';image.file=null;image.originalFile=null;if(!image.id)imageItems.splice(imageItems.indexOf(image),1);});colorItems.splice(colorItems.indexOf(item),1);activePhotoKey='';normalizeImageOrder();feedback('#color-feedback',choice==='move'?`El valor ${item.name} fue eliminado y sus fotografías se movieron a General.`:`El valor ${item.name} y sus fotografías se eliminarán al guardar.`);renderOptionState();});
  form.querySelector('#add-size').addEventListener('click',()=>{collectOptions();sizeItems.push({clientId:makeKey('size'),name:`Valor ${sizeItems.length+1}`});renderSizes();renderMatrix();});
  sizesRoot.addEventListener('click',event=>{const button=event.target.closest('[data-remove-size]');if(!button)return;collectOptions();const item=sizeItems.find(size=>size.clientId===button.parentElement.dataset.key);sizeItems.splice(sizeItems.indexOf(item),1);renderSizes();renderMatrix();});
  sizesRoot.addEventListener('change',()=>{collectOptions();renderSizes();renderMatrix();});
  const processImageItem=async image=>{
    if(image.deleted||editorClosed)return;
    image.controller=new AbortController();
    try{
      image.status='preparing';image.statusDetail='Verificando el archivo…';renderPhotoManager();
      image.fingerprint=await imageFingerprint(image.originalFile);
      const duplicate=imageItems.find(item=>item!==image&&!item.deleted&&item.fingerprint===image.fingerprint);
      if(duplicate){
        image.deleted=true;
        if(image.objectUrl)URL.revokeObjectURL(image.objectUrl);
        image.objectUrl='';
        imageItems.splice(imageItems.indexOf(image),1);
        normalizeImageOrder();
        feedback('#photo-feedback',`“${image.name}” ya estaba agregada y no se duplicó.`);
        renderPhotoManager();
        return;
      }
      const result=await prepareProductImage(image.originalFile,{signal:image.controller.signal,onStatus:status=>{if(image.deleted||editorClosed)return;image.status=status;image.statusDetail=status==='preparing'?'Verificando formato y orientación…':'Reduciendo peso sin recortar la fotografía…';renderPhotoManager();}});
      if(image.deleted||editorClosed)return;
      if(image.objectUrl)URL.revokeObjectURL(image.objectUrl);
      image.file=result.file;
      image.originalFile=null;
      image.name=result.file.name;
      image.objectUrl=URL.createObjectURL(result.file);
      image.url=image.objectUrl;
      image.optimization=result;
      image.status='ready';
      image.error=null;
      image.errorStage='';
      image.statusDetail=result.optimized?`${result.originalWidth}×${result.originalHeight}px → ${result.finalWidth}×${result.finalHeight}px · ${formatBytes(result.originalBytes)} → ${formatBytes(result.finalBytes)} · ${result.mime.replace('image/','').toUpperCase()}`:`Sin cambios · ${result.finalWidth}×${result.finalHeight}px · ${formatBytes(result.finalBytes)} · ${result.mime.replace('image/','').toUpperCase()}`;
      feedback('#photo-feedback',result.optimized?`“${image.name}” fue optimizada y está lista para subir.`:`“${image.name}” ya tenía un tamaño adecuado.`);
    }catch(error){
      if(error?.name==='AbortError')return;
      console.error(`No se pudo procesar ${image.name}:`,error);
      image.status='error';
      image.error=error;
      image.errorStage='processing';
      image.statusDetail=imageProcessingMessage(error);
      feedback('#photo-feedback',image.statusDetail,true);
    }finally{
      image.controller=null;
      if(!editorClosed)renderPhotoManager();
    }
  };
  const queueImageProcessing=image=>{processingQueue=processingQueue.then(()=>processImageItem(image)).catch(error=>console.error('Falló la cola de imágenes:',error));};
  const addFiles=fileList=>{
    const MAX_COUNT=40;
    const files=[...fileList];
    const remaining=Math.max(0,MAX_COUNT-imageItems.filter(item=>!item.deleted).length);
    const selected=files.slice(0,remaining);
    selected.forEach(file=>{
      const exceedsInputLimit=file.size>IMAGE_LIMITS.maxInputBytes;
      const objectUrl='';
      const image={clientId:makeKey('image'),colorKey:activePhotoKey,file:null,originalFile:file,name:file.name||'Fotografía',url:objectUrl,objectUrl,isPrimary:false,sortOrder:imageItems.length,status:exceedsInputLimit?'error':'preparing',statusDetail:exceedsInputLimit?'Esta fotografía supera 50 MB. Elige una imagen más pequeña para proteger el rendimiento del teléfono.':'Preparando vista previa…',errorStage:exceedsInputLimit?'processing':'',deleted:false};
      imageItems.push(image);
      if(!exceedsInputLimit)queueImageProcessing(image);
    });
    normalizeImageOrder();
    if(selected.length&&!imageItems.some(item=>!item.deleted&&item.isPrimary)){const first=imageItems.find(item=>!item.deleted);if(first)first.isPrimary=true;}
    const omitted=files.length-selected.length;
    const oversized=selected.filter(file=>file.size>IMAGE_LIMITS.maxInputBytes).length;
    const destination=colorItems.find(item=>item.clientId===activePhotoKey)?.name||'General';
    const accepted=selected.length-oversized;
    feedback('#photo-feedback',oversized?`${accepted} fotografía${accepted===1?'':'s'} en preparación. ${oversized} supera${oversized===1?'':'n'} el límite seguro de 50 MB.`:omitted?`${selected.length} fotografía${selected.length===1?'':'s'} en preparación para ${destination}. El máximo es ${MAX_COUNT}; ${omitted} no se agregó.`:`${selected.length} fotografía${selected.length===1?'':'s'} en preparación para ${destination}.`,oversized>0||omitted>0);
    renderPhotoManager();
  };
  const fileInput=form.querySelector('#product-files');const chooseFiles=form.querySelector('#choose-product-files');chooseFiles.addEventListener('click',()=>{try{if(typeof fileInput.showPicker==='function'){fileInput.showPicker();return;}}catch(error){console.warn('El selector moderno no estuvo disponible; se usará el selector compatible.',error);}fileInput.click();});fileInput.addEventListener('change',event=>{addFiles(event.target.files);event.target.value='';});const dropzone=form.querySelector('#photo-dropzone');['dragenter','dragover'].forEach(type=>dropzone.addEventListener(type,event=>{event.preventDefault();dropzone.classList.add('is-dragging');}));['dragleave','drop'].forEach(type=>dropzone.addEventListener(type,event=>{event.preventDefault();dropzone.classList.remove('is-dragging');}));dropzone.addEventListener('drop',event=>addFiles(event.dataTransfer.files));
  form.querySelector('#photo-tabs').addEventListener('click',event=>{const button=event.target.closest('[data-photo-tab]');if(!button)return;activePhotoKey=button.dataset.photoTab;renderPhotoManager();});
  form.querySelector('#photo-gallery').addEventListener('change',event=>{const select=event.target.closest('[data-photo-color]');if(!select)return;const image=imageItems.find(item=>item.clientId===select.dataset.photoColor);image.colorKey=select.value;feedback('#photo-feedback',`La fotografía fue movida a ${colorItems.find(item=>item.clientId===select.value)?.name||'General'}.`);renderPhotoManager();});
  form.querySelector('#photo-gallery').addEventListener('click',event=>{const card=event.target.closest('[data-photo]');if(!card)return;const image=imageItems.find(item=>item.clientId===card.dataset.photo);if(event.target.closest('[data-set-primary]')){imageItems.forEach(item=>{item.isPrimary=false;});image.isPrimary=true;feedback('#photo-feedback','La imagen principal fue actualizada.');renderPhotoManager();return;}if(event.target.closest('[data-remove-photo]')){image.controller?.abort();if(image.objectUrl)URL.revokeObjectURL(image.objectUrl);image.objectUrl='';image.file=null;image.originalFile=null;if(image.id)image.deleted=true;else imageItems.splice(imageItems.indexOf(image),1);if(image.isPrimary){const fallback=imageItems.find(item=>!item.deleted&&!item.colorKey)||imageItems.find(item=>!item.deleted);if(fallback)fallback.isPrimary=true;}normalizeImageOrder();feedback('#photo-feedback',image.id?'La fotografía se eliminará al guardar.':'La fotografía fue retirada.');renderPhotoManager();return;}if(event.target.closest('[data-retry-photo]')){if(image.errorStage==='processing'&&image.originalFile){image.status='preparing';image.statusDetail='Preparando un nuevo intento…';queueImageProcessing(image);renderPhotoManager();}else{image.status='ready';image.error=null;image.errorStage='';form.requestSubmit(form.querySelector('.form-actions [type="submit"]'));}return;}const move=event.target.closest('[data-photo-move]');if(move){const visible=imageItems.filter(item=>!item.deleted&&item.colorKey===activePhotoKey);const current=visible.indexOf(image);const other=visible[current+(move.dataset.photoMove==='up'?-1:1)];if(!other)return;const a=imageItems.indexOf(image);const b=imageItems.indexOf(other);[imageItems[a],imageItems[b]]=[imageItems[b],imageItems[a]];normalizeImageOrder();renderPhotoManager();}});
  const categorySelector=form.querySelector('.product-category-selector');
  const updateCategorySelection=()=>{const selected=[...categorySelector.querySelectorAll('[name="categoryIds"]:checked')];form.querySelector('[data-category-count]').textContent=`${selected.length} categor${selected.length===1?'ía':'ías'} seleccionada${selected.length===1?'':'s'}`;form.querySelector('[data-category-chips]').innerHTML=selected.map(input=>{const category=categories.find(item=>item.id===input.value);return`<button type="button" data-category-remove="${input.value}" aria-label="Quitar ${escapeHtml(categoryPath(category))}">${escapeHtml(categoryPath(category))}<span aria-hidden="true">×</span></button>`;}).join('');};
  const filterCategoryTree=()=>{const query=cleanText(form.querySelector('[data-category-search-input]').value);const nodes=[...categorySelector.querySelectorAll('[data-category-node]')];nodes.forEach(node=>{node.hidden=Boolean(query&&!node.dataset.categorySearch.includes(query));});categorySelector.querySelectorAll('[data-category-toggle]').forEach(button=>{const children=form.querySelector(`[data-category-children="${button.dataset.categoryToggle}"]`);if(!button.dataset.userExpanded)button.dataset.userExpanded=button.getAttribute('aria-expanded');if(query){const hasVisibleChild=[...children.children].some(node=>!node.hidden);children.hidden=!hasVisibleChild;button.setAttribute('aria-expanded',String(hasVisibleChild));}else{const expanded=button.dataset.userExpanded==='true';children.hidden=!expanded;button.setAttribute('aria-expanded',String(expanded));}});form.querySelector('[data-category-empty]').hidden=nodes.some(node=>!node.hidden);};
  categorySelector.addEventListener('click',event=>{const remove=event.target.closest('[data-category-remove]');if(remove){const input=categorySelector.querySelector(`[name="categoryIds"][value="${remove.dataset.categoryRemove}"]`);if(input)input.checked=false;updateCategorySelection();return;}const button=event.target.closest('[data-category-toggle]');if(!button)return;const expanded=button.dataset.userExpanded==='true'||(!button.dataset.userExpanded&&button.getAttribute('aria-expanded')==='true');button.dataset.userExpanded=String(!expanded);button.setAttribute('aria-expanded',String(!expanded));form.querySelector(`[data-category-children="${button.dataset.categoryToggle}"]`).hidden=expanded;});categorySelector.addEventListener('change',event=>{if(event.target.matches('[name="categoryIds"]'))updateCategorySelection();});form.querySelector('[data-category-search-input]').addEventListener('input',filterCategoryTree);
  form.querySelector('[data-add-spec]').addEventListener('click',()=>{specsRoot.insertAdjacentHTML('beforeend',specificationRow());specsRoot.lastElementChild.querySelector('input').focus();});specsRoot.addEventListener('click',event=>{const button=event.target.closest('[data-remove-spec]');if(button)button.closest('[data-spec-row]').remove();});
  const syncOptionLabels=()=>{form.querySelector('[data-option1-label]').textContent=`Valores de ${optionName(1).toLocaleLowerCase('es')}`;form.querySelector('[data-option2-label]').textContent=`Valores de ${optionName(2).toLocaleLowerCase('es')}`;collectMatrix();renderMatrix();};['option1_name','option2_name'].forEach(name=>form.elements[name].addEventListener('input',syncOptionLabels));
  form.querySelector('[data-preview-form]').addEventListener('click',()=>{const primary=imageItems.find(image=>!image.deleted&&image.isPrimary)||imageItems.find(image=>!image.deleted);openModal({title:'Vista previa del producto',content:productPreviewMarkup({...collectProductValues(form),preview_image:primary?.objectUrl||primary?.url}),className:'modal--product-preview'});});
  form.addEventListener('submit',async event=>{
    event.preventDefault();
    if(formSaving)return;
    clearFormError();collectOptions();
    const processing=imageItems.find(image=>!image.deleted&&isProcessing(image));
    if(processing){showFormError('Espera a que terminemos de optimizar las fotografías.',form.querySelector('#photo-progress'));return;}
    const processingError=imageItems.find(image=>!image.deleted&&image.status==='error'&&image.errorStage==='processing');
    if(processingError){showFormError('Reintenta o elimina la fotografía que no se pudo procesar.',form.querySelector(`[data-photo="${processingError.clientId}"] [data-retry-photo]`));return;}
    const name=form.elements.name;const duplicate=colorItems.find(item=>duplicateColor(item.name,item.clientId));
    if(!name.value.trim()){name.setAttribute('aria-invalid','true');showFormError('Escribe el nombre del producto.',name);return;}
    const basePrice=Number(form.elements.base_price.value);
    if(!Number.isFinite(basePrice)||basePrice<0){form.elements.base_price.setAttribute('aria-invalid','true');showFormError('Ingresa un precio válido igual o mayor que cero.',form.elements.base_price);return;}
    if(colorItems.some(item=>!item.name)||duplicate){showFormError(duplicate?'Hay un valor repetido en la opción 1.':'Todos los valores de la opción 1 deben tener nombre.',colorsRoot.querySelector(`[data-color-name="${duplicate?.clientId||colorItems.find(item=>!item.name)?.clientId}"]`));return;}
    if(!sizeItems.length||sizeItems.some(item=>!item.name)){showFormError('Agrega al menos un valor con nombre en la opción 2 (usa “Única” si no aplica).',!sizeItems.length?form.querySelector('#add-size'):sizesRoot.querySelector('input:invalid'));return;}

    const button=event.submitter||form.querySelector('[type="submit"]');
    formSaving=true;setButtonLoading(button,true,'Guardando…');renderPhotoManager();
    try{
      const values=collectProductValues(form);
      for(const field of ['size_guide_image_url']){
        const file=form.querySelector(`[data-upload="${field}"]`)?.files[0];
        if(file){setButtonLoading(button,true,'Optimizando imágenes…');const prepared=await prepareProductImage(file);values[field]=await uploadImage('product-images',prepared.file,'templates');}
      }
      setButtonLoading(button,true,'Guardando producto…');
      const saved=await saveRow('products',values,savedProductId);savedProductId=saved.id;
      const categoryIds=[...form.querySelectorAll('[name="categoryIds"]:checked')].map(input=>input.value);
      const relation=await prepareProductRelations(saved.id,{categoryIds,colors:colorItems,sizes:sizeItems});
      relation.savedColors.forEach(savedColor=>{const item=colorItems.find(color=>color.clientId===savedColor.client_id);if(item)item.id=savedColor.id;});
      relation.savedSizes.forEach(savedSize=>{const item=sizeItems.find(size=>size.clientId===savedSize.client_id);if(item)item.id=savedSize.id;});
      normalizeImageOrder();
      const colorIds=new Map(relation.savedColors.map(color=>[color.client_id,color.id]));
      setButtonLoading(button,true,'Subiendo fotografías…');
      await syncProductImages(saved.id,imageItems,colorIds,()=>renderPhotoManager());
      const variants=[...stockMap].map(([key,stock])=>{const[colorKey,sizeKey]=key.split('|');return{colorKey,sizeKey,stock,active:true};});
      await finalizeProductRelations(saved.id,{...relation,variants});
      await refreshData();modal.close(true);loadSection(activeSection);toast('Producto guardado correctamente');
    }catch(error){
      console.error(error,error.imageFailures?.map(failure=>failure.error?.message));
      if(error.imageFailures){renderPhotoManager();showFormError(error.message,form.querySelector('.photo-card__status--error'));toast(error.userMessage||'No pudimos subir una fotografía. Puedes reintentar sin seleccionarla de nuevo.','error');}
      else if(error?.code){const message=imageProcessingMessage(error);showFormError(message);toast(message,'error');}
      else{showFormError('No pudimos guardar el producto. Revisa los datos e intenta nuevamente.');toast('Hubo un problema al guardar los cambios. Revisa los datos.','error');}
    }finally{
      formSaving=false;
      if(!editorClosed){setButtonLoading(button,false);renderPhotoManager();}
    }
  });
  renderOptionState();updateCategorySelection();syncOptionLabels();initialSignature=editorSignature();
}

function productFormMarkup(p){
  const val=(key,fallback='')=>escapeHtml(p?.[key]??fallback);const checked=key=>p?.[key]?'checked':'';
  return `<p class="product-form-error" data-product-form-error role="alert" tabindex="-1" hidden></p>
  <section class="admin-form__section"><div class="admin-form__section-head"><span>1</span><div><h3>Información básica</h3><p>Los datos principales que identifican el producto.</p></div></div><div class="form-grid"><label>Nombre<input name="name" value="${val('name')}" required maxlength="160" autocomplete="off"></label><label>Slug <small>Opcional</small><input name="slug" value="${val('slug')}" placeholder="Se genera automáticamente" autocomplete="off"></label><label>SKU / referencia <small>Opcional</small><input name="sku" value="${val('sku')}" maxlength="80"></label><label>Modelo <small>Opcional</small><input name="model" value="${val('model')}" maxlength="120"></label><label class="form-grid__full">Descripción <small>Se muestra en Detalles del producto</small><textarea name="description" rows="3" placeholder="Describe las características principales">${val('description')}</textarea></label><label>Precio de venta<input name="base_price" type="number" min="0" step="1000" value="${val('base_price',0)}" required inputmode="numeric"></label><label>Marca <small>Opcional</small><select name="brand_id"><option value="">Sin marca</option>${brands.map(item=>`<option value="${item.id}" ${p?.brand_id===item.id?'selected':''}>${escapeHtml(item.name)}</option>`).join('')}</select></label></div></section>
  <section class="admin-form__section"><div class="admin-form__section-head"><span>2</span><div><h3>Categorías</h3><p>Seleccionar y desplegar son acciones independientes.</p></div></div>${categorySelectorMarkup(p)}</section>
  <section class="admin-form__section" data-product-photo-section></section>
  <section class="admin-form__section" data-product-option-section></section>
  <section class="admin-form__section"><div class="admin-form__section-head"><span>5</span><div><h3>Inventario por variante</h3><p>Stock disponible para cada combinación de opciones. Un producto publicado sin stock sigue visible como “Agotado”.</p></div></div><div id="variant-matrix" class="variant-matrix"></div><div class="form-grid product-force-status"><label>Avisar stock bajo desde <small>unidades</small><input name="low_stock_threshold" type="number" min="0" step="1" value="${val('low_stock_threshold',3)}" inputmode="numeric"></label><label class="check-field"><input name="force_last_units" type="checkbox" ${checked('force_last_units')}> Marcar como últimas unidades</label><label class="check-field"><input name="force_sold_out" type="checkbox" ${checked('force_sold_out')}> Marcar como agotado</label></div></section>
  <section class="admin-form__section"><div class="admin-form__section-head"><span>6</span><div><h3>Promoción</h3><p>Opcional. El precio promocional debe ser menor al normal.</p></div></div><div class="form-grid"><label>Precio promocional <small>Opcional</small><input name="promo_price" type="number" min="0" step="1000" value="${val('promo_price')}" inputmode="numeric"></label><label>Inicio <small>Opcional</small><input name="promo_start" type="datetime-local" value="${toLocalInput(p?.promo_start)}"></label><label>Finalización <small>Opcional</small><input name="promo_end" type="datetime-local" value="${toLocalInput(p?.promo_end)}"></label><label class="check-field"><input name="promo_enabled" type="checkbox" ${p?.promo_enabled!==false?'checked':''}> Promoción habilitada</label></div></section>
  <section class="admin-form__section"><div class="admin-form__section-head"><span>7</span><div><h3>Información del producto</h3><p>Contenido específico que aparecerá en la ficha pública.</p></div></div><details class="admin-form-disclosure" open><summary>Uso y cuidado <span aria-hidden="true">⌄</span></summary><div class="admin-form-disclosure__body form-grid"><label>Materiales <small>Opcional</small><textarea name="material" rows="3" placeholder="Ej. Acero inoxidable">${val('material')}</textarea></label><label>Uso y cuidado <small>Opcional</small><textarea name="care_instructions" rows="3" placeholder="Recomendaciones de instalación, uso o limpieza">${val('care_instructions')}</textarea></label></div></details><details class="admin-form-disclosure"><summary>Compra y entrega <small>Opcional</small><span aria-hidden="true">⌄</span></summary><div class="admin-form-disclosure__body"><label>Información para este producto<textarea name="purchase_delivery_info" rows="3" placeholder="Condiciones de entrega o instalación específicas de este producto">${val('purchase_delivery_info')}</textarea></label></div></details></section>
  <section class="admin-form__section"><div class="admin-form__section-head"><span>8</span><div><h3>Especificaciones técnicas</h3><p>Opcional. Agrega solo las que apliquen: capacidad, potencia, dimensiones, almacenamiento, voltaje, edad recomendada…</p></div></div><div class="dynamic-list" data-specs>${specificationItems(p?.specifications).map(item=>specificationRow(item)).join('')}</div><button class="small-btn" data-add-spec type="button">+ Característica</button></section>
  <section class="admin-form__section"><div class="admin-form__section-head"><span>9</span><div><h3>Publicación</h3><p>Controla dónde estará visible el producto.</p></div></div><div class="form-grid"><label>Estado<select name="status"><option value="draft" ${!p||p?.status==='draft'?'selected':''}>Borrador</option><option value="published" ${p?.status==='published'?'selected':''}>Publicado</option><option value="hidden" ${p?.status==='hidden'?'selected':''}>Oculto</option></select></label><label class="check-field"><input name="featured" type="checkbox" ${checked('featured')}> Destacado en inicio</label></div></section>
  <div class="form-actions"><button class="btn btn--primary" type="submit">Guardar producto</button><button class="btn btn--ghost" data-preview-form type="button">Vista previa</button></div>`;
}

function collectProductValues(form){const data=new FormData(form);const nullable=value=>String(value||'').trim()||null;const specs=[...form.querySelectorAll('[data-spec-row]')].map(row=>({label:row.querySelector('[data-spec-label]').value.trim(),value:row.querySelector('[data-spec-value]').value.trim()})).filter(item=>item.label&&item.value);return{name:nullable(data.get('name'))||'',slug:nullable(data.get('slug'))||slugify(data.get('name')),sku:nullable(data.get('sku')),model:nullable(data.get('model')),description:nullable(data.get('description')),material:nullable(data.get('material')),care_instructions:nullable(data.get('care_instructions')),purchase_delivery_info:nullable(data.get('purchase_delivery_info')),specifications:specs.length?{items:specs}:{},option1_name:nullable(data.get('option1_name')),option2_name:nullable(data.get('option2_name')),low_stock_threshold:Math.max(0,Math.round(Number(data.get('low_stock_threshold')??3)||0)),base_price:Number(data.get('base_price')),promo_price:data.get('promo_price')?Number(data.get('promo_price')):null,promo_start:nullable(data.get('promo_start')?new Date(data.get('promo_start')).toISOString():null),promo_end:nullable(data.get('promo_end')?new Date(data.get('promo_end')).toISOString():null),promo_enabled:data.has('promo_enabled'),status:data.get('status'),brand_id:nullable(data.get('brand_id')),featured:data.has('featured'),force_last_units:data.has('force_last_units'),force_sold_out:data.has('force_sold_out'),size_guide_text:nullable(data.get('size_guide_text')),size_guide_image_url:nullable(data.get('size_guide_image_url'))};}
function toLocalInput(value){if(!value)return'';const d=new Date(value);d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,16);}

function renderProducts(){
  const params=new URLSearchParams(location.search);
  const state={search:params.get('search')||'',status:params.get('status')||'all',category:params.get('category')||'',brand:params.get('brand')||'',page:Math.max(1,Number(params.get('page'))||1)};
  if(!['all','published','draft','hidden'].includes(state.status))state.status='all';
  $('#admin-content').innerHTML=heading('Catálogo','Productos','Encuentra, publica y edita productos sin perder contexto.','<button id="new-product" class="btn btn--primary" type="button">+ Nuevo producto</button>')+`<section class="admin-panel"><div class="admin-panel__head"><h2>Catálogo</h2><p>${products.length} productos registrados</p></div><div class="admin-toolbar"><div class="admin-search-wrap"><input id="admin-product-search" class="admin-search" type="search" value="${escapeHtml(state.search)}" placeholder="Buscar por nombre, referencia o marca" aria-label="Buscar productos"></div><button id="product-filters-button" class="toolbar-button" type="button" aria-expanded="false" aria-controls="product-filter-panel">Filtros</button><div class="admin-chips" role="group" aria-label="Filtrar por estado"><button class="filter-chip ${state.status==='all'?'active':''}" data-product-status="all" type="button">Todos</button><button class="filter-chip ${state.status==='published'?'active':''}" data-product-status="published" type="button">Publicados</button><button class="filter-chip ${state.status==='draft'?'active':''}" data-product-status="draft" type="button">Borradores</button><button class="filter-chip ${state.status==='hidden'?'active':''}" data-product-status="hidden" type="button">Ocultos</button></div><div id="product-filter-panel" class="filter-panel" hidden>${selectFilter('product-category','Categoría',categories,state.category)}${selectFilter('product-brand','Marca',brands,state.brand)}<div class="filter-panel__wide"><button id="clear-product-filters" class="small-btn" type="button">Limpiar filtros</button></div></div></div><div id="admin-product-results"></div></section>`;
  const renderResults=()=>{
    const filtered=products.filter(product=>{const haystack=cleanText([product.name,product.brands?.name].join(' '));return(!state.search||haystack.includes(cleanText(state.search)))&&(state.status==='all'||product.status===state.status)&&(!state.category||product.product_categories.some(row=>row.category_id===state.category))&&(!state.brand||product.brand_id===state.brand);});
    const pages=Math.max(1,Math.ceil(filtered.length/PAGE_SIZE));state.page=Math.min(state.page,pages);const visible=filtered.slice((state.page-1)*PAGE_SIZE,state.page*PAGE_SIZE);
    $('#admin-product-results').innerHTML=`<div class="results-meta"><span>${filtered.length} ${filtered.length===1?'resultado':'resultados'}</span></div>${visible.length?productRows(visible):emptyMarkup('No encontramos productos','Prueba otra búsqueda o limpia los filtros.')}${paginationMarkup(state.page,pages)}`;
    bindProductRowActions(renderProducts);bindPagination($('#admin-product-results'),state,pages,renderResults);syncSectionUrl('products',state);
  };
  $('#new-product').addEventListener('click',()=>openProductForm());
  $('#product-filters-button').addEventListener('click',event=>{const panel=$('#product-filter-panel');panel.hidden=!panel.hidden;event.currentTarget.setAttribute('aria-expanded',String(!panel.hidden));});
  $$('[data-product-status]').forEach(button=>button.addEventListener('click',()=>{state.status=button.dataset.productStatus;state.page=1;$$('[data-product-status]').forEach(item=>item.classList.toggle('active',item===button));renderResults();}));
  const search=debounce(value=>{state.search=value;state.page=1;renderResults();});$('#admin-product-search').addEventListener('input',event=>search(event.target.value));
  [['#product-category','category'],['#product-brand','brand']].forEach(([selector,key])=>$(selector).addEventListener('change',event=>{state[key]=event.target.value;state.page=1;renderResults();}));
  $('#clear-product-filters').addEventListener('click',()=>navigateTo('products'));renderResults();
}

function selectFilter(id,label,items,value){return `<label>${label}<select id="${id}"><option value="">Todos</option>${items.map(item=>`<option value="${item.id}" ${value===item.id?'selected':''}>${escapeHtml(item.name)}</option>`).join('')}</select></label>`;}
function syncSectionUrl(section,state){const query=new URLSearchParams({section});Object.entries(state).forEach(([key,value])=>{if(value&&value!=='all'&&!(key==='page'&&value===1))query.set(key,value);});history.replaceState({},'',`${location.pathname}?${query}`);}
function paginationMarkup(page,pages){if(pages<=1)return'';return `<nav class="pagination" aria-label="Paginación"><button data-page="${page-1}" ${page===1?'disabled':''} type="button">← Anterior</button><span>Página ${page} de ${pages}</span><button data-page="${page+1}" ${page===pages?'disabled':''} type="button">Siguiente →</button></nav>`;}
function bindPagination(root,state,pages,render){root.querySelectorAll('[data-page]').forEach(button=>button.addEventListener('click',()=>{state.page=Math.min(pages,Math.max(1,Number(button.dataset.page)));render();root.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});}));}
function emptyMarkup(title,text){return `<div class="empty-state empty-state--admin"><h3>${title}</h3><p>${text}</p></div>`;}
function formatUpdated(value){const date=new Date(value);const diff=Math.floor((Date.now()-date.getTime())/86400000);if(diff<=0)return'hoy';if(diff===1)return'ayer';if(diff<7)return`hace ${diff} días`;return date.toLocaleDateString('es-CO',{day:'numeric',month:'short'});}

function productRows(items){return `<div class="data-list">${items.map(product=>`<article class="data-row" data-product="${product.id}"><div class="data-row__thumb"><img src="${escapeHtml(productImage(product))}" alt="" loading="lazy" width="52" height="52"></div><div class="data-row__main"><strong>${escapeHtml(product.name)}</strong><small>${formatMoney(currentPrice(product))} · Actualizado ${formatUpdated(product.updated_at)}</small></div><span class="status-pill status-pill--${product.status}">${product.status==='published'?'Publicado':product.status==='hidden'?'Oculto':'Borrador'}</span><div class="data-row__actions"><button class="small-btn" data-edit type="button">Editar</button><details class="action-menu"><summary aria-label="Más acciones">⋮</summary><div class="action-menu__popover"><button data-preview type="button">Vista previa</button><button data-toggle type="button">${product.status==='published'?'Ocultar':'Publicar'}</button><button data-delete type="button">Eliminar</button></div></details></div></article>`).join('')}</div>`;}

function bindProductRowActions(afterChange=renderProducts){
  $$('.data-row[data-product]').forEach(row=>{const product=products.find(item=>item.id===row.dataset.product);if(!product)return;
    row.querySelector('[data-preview]')?.addEventListener('click',()=>window.open(`../producto.html?slug=${encodeURIComponent(product.slug)}`,'_blank','noopener'));
    row.querySelector('[data-edit]')?.addEventListener('click',()=>openProductForm(product));
    row.querySelector('[data-toggle]')?.addEventListener('click',async event=>{event.currentTarget.disabled=true;try{await saveRow('products',{status:product.status==='published'?'hidden':'published'},product.id);await refreshData();afterChange();toast('Estado actualizado');}catch(error){console.error(error);event.currentTarget.disabled=false;toast('No pudimos cambiar el estado.','error');}});
    row.querySelector('[data-delete]')?.addEventListener('click',async()=>{if(!await confirmAction(`¿Eliminar “${product.name}”? Esta acción también elimina sus variantes e imágenes registradas.`,'Eliminar producto'))return;try{await deleteRow('products',product.id);await refreshData();afterChange();toast('Producto eliminado');}catch(error){console.error(error);toast('No pudimos eliminar el producto.','error');}});
  });
}

function renderStock(){
  const params=new URLSearchParams(location.search);
  const allVariants=products.flatMap(product=>product.product_variants.map(variant=>({...variant,product,color:product.product_colors.find(color=>color.id===variant.color_id)?.name||'Única',size:product.product_sizes.find(size=>size.id===variant.size_id)?.name||'Única'})));
  const colors=[...new Set(allVariants.map(variant=>variant.color))].sort((a,b)=>a.localeCompare(b));const sizes=[...new Set(allVariants.map(variant=>variant.size))];
  const state={search:params.get('search')||'',status:['all','low','out','available'].includes(params.get('status'))?params.get('status'):'all',category:params.get('category')||'',brand:params.get('brand')||'',color:params.get('color')||'',size:params.get('size')||'',sort:params.get('sort')||'name',page:Math.max(1,Number(params.get('page'))||1)};
  $('#admin-content').innerHTML=heading('Inventario','Stock rápido',`${allVariants.length} variantes · ${products.length} productos. Los pedidos por WhatsApp no descuentan stock.`)+`<section class="admin-panel"><div class="admin-toolbar admin-toolbar--sticky"><div class="admin-search-wrap"><input id="stock-search-v2" class="admin-search" type="search" value="${escapeHtml(state.search)}" placeholder="Producto, opción o referencia…" aria-label="Buscar en el inventario"></div><button id="stock-filters-button" class="toolbar-button" type="button" aria-expanded="false" aria-controls="stock-filter-panel">Filtros <span id="stock-filter-count"></span></button><div class="admin-chips" role="group" aria-label="Filtrar por disponibilidad"><button class="filter-chip ${state.status==='all'?'active':''}" data-stock-status="all" type="button">Todos</button><button class="filter-chip ${state.status==='low'?'active':''}" data-stock-status="low" type="button">Últimas unidades</button><button class="filter-chip ${state.status==='out'?'active':''}" data-stock-status="out" type="button">Agotados</button><button class="filter-chip ${state.status==='available'?'active':''}" data-stock-status="available" type="button">Disponibles</button></div><div id="stock-filter-panel" class="filter-panel" hidden>${selectFilter('stock-category','Categoría',categories,state.category)}${selectFilter('stock-brand','Marca',brands,state.brand)}${selectTextFilter('stock-color','Opción 1',colors,state.color)}${selectTextFilter('stock-size','Opción 2',sizes,state.size)}<label>Orden<select id="stock-sort"><option value="name" ${state.sort==='name'?'selected':''}>A–Z</option><option value="stock-asc" ${state.sort==='stock-asc'?'selected':''}>Menor stock</option><option value="stock-desc" ${state.sort==='stock-desc'?'selected':''}>Mayor stock</option><option value="updated" ${state.sort==='updated'?'selected':''}>Actualizados recientemente</option></select></label><div class="filter-panel__wide"><button id="clear-stock-filters" class="small-btn" type="button">Limpiar filtros</button></div></div></div><div id="stock-results-v2"></div></section>`;
  const renderResults=()=>{
    const query=cleanText(state.search);const queryWords=query.split(/\s+/).filter(Boolean);let groups=products.map(product=>{const productVariants=allVariants.filter(variant=>variant.product.id===product.id);const productHaystack=cleanText([product.name,product.brands?.name,...product.product_categories.map(row=>row.categories?.name)].join(' '));let matchingVariants=productVariants.filter(variant=>queryWords.every(word=>cleanText(`${productHaystack} ${variant.color} ${variant.size}`).includes(word)));matchingVariants=matchingVariants.filter(variant=>{const status=stockStatus(variant.stock,product).className;return(state.status==='all'||state.status===status||(state.status==='out'&&status==='sold'))&&(!state.color||variant.color===state.color)&&(!state.size||variant.size===state.size);});return{product,variants:matchingVariants,autoOpen:Boolean(query)||state.status!=='all'};}).filter(group=>group.variants.length&&(!state.category||group.product.product_categories.some(row=>row.category_id===state.category))&&(!state.brand||group.product.brand_id===state.brand));
    const updatedAt=group=>Math.max(new Date(group.product.updated_at).getTime(),...group.variants.map(variant=>new Date(variant.updated_at||0).getTime()));groups.sort((a,b)=>state.sort==='stock-asc'?totalStock(a.product)-totalStock(b.product):state.sort==='stock-desc'?totalStock(b.product)-totalStock(a.product):state.sort==='updated'?updatedAt(b)-updatedAt(a):a.product.name.localeCompare(b.product.name));
    const pages=Math.max(1,Math.ceil(groups.length/STOCK_PAGE_SIZE));state.page=Math.min(state.page,pages);const visible=groups.slice((state.page-1)*STOCK_PAGE_SIZE,state.page*STOCK_PAGE_SIZE);const variantCount=groups.reduce((sum,group)=>sum+group.variants.length,0);
    $('#stock-results-v2').innerHTML=`<div class="results-meta"><span>${groups.length} ${groups.length===1?'producto':'productos'} · ${variantCount} ${variantCount===1?'variante':'variantes'}</span><button id="toggle-stock-groups" type="button">${visible.some(group=>!group.autoOpen)?'Expandir resultados':'Contraer resultados'}</button></div>${visible.length?`<div class="stock-products">${visible.map(stockGroupMarkup).join('')}</div>`:emptyMarkup('No encontramos variantes','Prueba otra búsqueda o limpia los filtros.')}${paginationMarkup(state.page,pages)}`;
    bindStockControls(allVariants);bindPagination($('#stock-results-v2'),state,pages,renderResults);$('#toggle-stock-groups')?.addEventListener('click',event=>{const details=$$('#stock-results-v2 .stock-product');const open=details.some(item=>!item.open);details.forEach(item=>item.open=open);event.currentTarget.textContent=open?'Contraer resultados':'Expandir resultados';});updateStockFilterCount(state);syncSectionUrl('stock',state);
  };
  $('#stock-filters-button').addEventListener('click',event=>{const panel=$('#stock-filter-panel');panel.hidden=!panel.hidden;event.currentTarget.setAttribute('aria-expanded',String(!panel.hidden));});
  $$('[data-stock-status]').forEach(button=>button.addEventListener('click',()=>{state.status=button.dataset.stockStatus;state.page=1;$$('[data-stock-status]').forEach(item=>item.classList.toggle('active',item===button));renderResults();}));
  const search=debounce(value=>{state.search=value;state.page=1;renderResults();});$('#stock-search-v2').addEventListener('input',event=>search(event.target.value));
  [['#stock-category','category'],['#stock-brand','brand'],['#stock-color','color'],['#stock-size','size'],['#stock-sort','sort']].forEach(([selector,key])=>$(selector).addEventListener('change',event=>{state[key]=event.target.value;state.page=1;renderResults();}));
  $('#clear-stock-filters').addEventListener('click',()=>navigateTo('stock'));renderResults();
}

function selectTextFilter(id,label,items,value){return `<label>${label}<select id="${id}"><option value="">Todos</option>${items.map(item=>`<option value="${escapeHtml(item)}" ${value===item?'selected':''}>${escapeHtml(item)}</option>`).join('')}</select></label>`;}
function updateStockFilterCount(state){const count=['category','brand','color','size'].filter(key=>state[key]).length+(state.status!=='all'?1:0);$('#stock-filter-count').textContent=count?`(${count})`:'';}
function stockGroupMarkup(group){const sold=group.variants.filter(variant=>stockStatus(variant.stock,variant.product).className==='sold').length;const low=group.variants.filter(variant=>stockStatus(variant.stock,variant.product).className==='low').length;return `<details class="stock-product" data-stock-product="${group.product.id}" ${group.autoOpen?'open':''}><summary><span class="stock-product__thumb"><img src="${escapeHtml(productImage(group.product))}" alt="" loading="lazy" width="50" height="54"></span><span class="stock-product__copy"><strong>${escapeHtml(group.product.name)}</strong><small>${group.product.product_variants.length} variantes · ${totalStock(group.product)} unidades</small>${sold||low?`<span class="stock-product__alerts">${sold?`<span class="sold">${sold} agotada${sold===1?'':'s'}</span>`:''}${low?`<span>${low} con stock bajo</span>`:''}</span>`:''}</span><span class="stock-product__chevron" aria-hidden="true">⌄</span></summary><div class="stock-variants">${group.variants.map(stockRowMarkup).join('')}</div></details>`;}
function stockRowMarkup(variant){const status=stockStatus(variant.stock,variant.product);return `<article class="stock-row" data-variant="${variant.id}"><div class="stock-row__info"><strong>${escapeHtml([variant.color,variant.size].filter(value=>!/^única$/i.test(value)).join(' / ')||'Sin opciones')}</strong><span class="status-pill status-pill--${status.className}" data-stock-pill>${status.label}</span></div><div class="stock-row__actions"><div class="stock-control"><button data-minus type="button" aria-label="Restar una unidad">−</button><input type="number" min="0" step="1" inputmode="numeric" value="${variant.stock}" aria-label="Stock de ${escapeHtml(variant.product.name)} ${escapeHtml(variant.color)} ${escapeHtml(variant.size)}"><button data-plus type="button" aria-label="Sumar una unidad">+</button></div><span class="stock-save-state" data-save-state aria-live="polite"></span></div></article>`;}

function bindStockControls(variants){
  $$('.stock-row[data-variant]').forEach(row=>{const variant=variants.find(item=>item.id===row.dataset.variant);const input=row.querySelector('input');const controls=[row.querySelector('[data-minus]'),row.querySelector('[data-plus]')];const stateLabel=row.querySelector('[data-save-state]');let saving=false;
    const paint=value=>{const status=stockStatus(value,variant.product);const pill=row.querySelector('[data-stock-pill]');pill.className=`status-pill status-pill--${status.className}`;pill.textContent=status.label;refreshStockGroupSummary(row,variant.product);};
    const save=async raw=>{if(saving)return;const parsed=Number(raw);if(!Number.isInteger(parsed)||parsed<0){input.value=variant.stock;toast('El stock debe ser un número entero desde 0.','error');return;}if(parsed===variant.stock)return;const previous=variant.stock;saving=true;variant.stock=parsed;input.value=parsed;paint(parsed);controls.forEach(button=>button.disabled=true);input.disabled=true;stateLabel.className='stock-save-state stock-save-state--saving';stateLabel.textContent='Guardando…';try{await saveRow('product_variants',{stock:parsed},variant.id);stateLabel.className='stock-save-state stock-save-state--saved';stateLabel.textContent='✓ Guardado';setTimeout(()=>{if(stateLabel.textContent==='✓ Guardado')stateLabel.textContent='';},1800);}catch(error){console.error(error);variant.stock=previous;input.value=previous;paint(previous);stateLabel.className='stock-save-state stock-save-state--error';stateLabel.textContent='Error al guardar';toast('No pudimos actualizar el stock. Se restauró el valor anterior.','error');}finally{saving=false;controls.forEach(button=>button.disabled=false);input.disabled=false;}};
    row.querySelector('[data-minus]').addEventListener('click',()=>save(Math.max(0,Number(input.value)-1)));row.querySelector('[data-plus]').addEventListener('click',()=>save(Number(input.value)+1));input.addEventListener('keydown',event=>{if(['-','+','.','e','E'].includes(event.key))event.preventDefault();if(event.key==='Enter'){event.preventDefault();input.blur();}});input.addEventListener('blur',()=>save(input.value));
  });
}

function refreshStockGroupSummary(row,product){const copy=row.closest('.stock-product')?.querySelector('.stock-product__copy');if(!copy)return;copy.querySelector('small').textContent=`${product.product_variants.length} variantes · ${totalStock(product)} unidades`;const statuses=product.product_variants.map(variant=>stockStatus(variant.stock,product).className);const sold=statuses.filter(status=>status==='sold').length;const low=statuses.filter(status=>status==='low').length;let alerts=copy.querySelector('.stock-product__alerts');if(!sold&&!low){alerts?.remove();return;}if(!alerts){alerts=document.createElement('span');alerts.className='stock-product__alerts';copy.append(alerts);}alerts.innerHTML=`${sold?`<span class="sold">${sold} agotada${sold===1?'':'s'}</span>`:''}${low?`<span>${low} con stock bajo</span>`:''}`;}

function entityLoadingMarkup(){return `<section class="admin-skeleton" aria-label="Cargando registros" aria-busy="true"><span class="skeleton-block skeleton-block--title"></span><span class="skeleton-block skeleton-block--search"></span>${Array.from({length:5},()=>'<span class="skeleton-block skeleton-block--row"></span>').join('')}</section>`;}

function getEntityConfig(type){
  return {
    categories:{title:'Categorías',singular:'categoría',plural:'categorías',items:categories,button:'Nueva categoría',placeholder:'Buscar categoría o subcategoría',quickKey:'status',quickOptions:[['all','Todas'],['active','Activas'],['inactive','Inactivas']],kindOptions:[['all','Todas'],['parent','Categorías principales'],['child','Subcategorías']]},
    brands:{title:'Marcas',singular:'marca',plural:'marcas',items:brands,button:'Nueva marca',placeholder:'Buscar marca…',quickKey:'status',quickOptions:[['all','Todas'],['active','Activas'],['inactive','Inactivas']],kindOptions:[]}
  }[type];
}

function getEntityState(type){
  const params=new URLSearchParams(location.search);const state={search:params.get('search')||'',status:params.get('status')||'all',kind:params.get('kind')||'all',sort:params.get('sort')||'az',page:Math.max(1,Number(params.get('page'))||1),parent:type==='categories'?(params.get('parent')||''):''};
  if(!['all','active','inactive'].includes(state.status))state.status='all';
  const allowedKinds=type==='categories'?['all','parent','child']:['all'];if(!allowedKinds.includes(state.kind))state.kind='all';
  if(!['az','za','newest','oldest'].includes(state.sort))state.sort='az';return state;
}

function entityKindLabel(type,item){
  if(type==='categories')return item.parent_id?'Subcategoría':'Categoría principal';
  if(type==='brands')return'Marca';
  return'Elemento';
}

function entitySortOptions(value){return `<option value="az" ${value==='az'?'selected':''}>A–Z</option><option value="za" ${value==='za'?'selected':''}>Z–A</option><option value="newest" ${value==='newest'?'selected':''}>Más recientes</option><option value="oldest" ${value==='oldest'?'selected':''}>Más antiguos</option>`;}

function entityFilterPanel(type,config,state){
  const kind=config.kindOptions.length?`<label>Tipo<select data-entity-filter="kind">${config.kindOptions.map(([value,label])=>`<option value="${value}" ${state.kind===value?'selected':''}>${label}</option>`).join('')}</select></label>`:'';const feminine=true;
  return `<div id="entity-filter-panel" class="filter-panel entity-filter-panel" hidden><label>Estado<select data-entity-filter="status"><option value="all" ${state.status==='all'?'selected':''}>${feminine?'Todas':'Todos'}</option><option value="active" ${state.status==='active'?'selected':''}>${feminine?'Activas':'Activos'}</option><option value="inactive" ${state.status==='inactive'?'selected':''}>${feminine?'Inactivas':'Inactivos'}</option></select></label>${kind}<label class="entity-filter-sort">Orden<select data-entity-filter="sort">${entitySortOptions(state.sort)}</select></label><div class="filter-panel__wide"><button class="small-btn" data-clear-entities type="button">Limpiar filtros</button></div></div>`;
}

function entityToolbar(type,config,state){
  const quickLabel=config.quickKey==='status'?'Filtrar por estado':'Filtrar por tipo';
  return `<div class="entity-toolbar"><div class="entity-toolbar__sticky"><div class="admin-search-wrap"><input id="entity-search" class="admin-search" type="search" value="${escapeHtml(state.search)}" placeholder="${escapeHtml(config.placeholder)}" aria-label="${escapeHtml(config.placeholder)}" autocomplete="off"></div><button id="entity-filters-button" class="toolbar-button" type="button" aria-expanded="false" aria-controls="entity-filter-panel">Filtros <span id="entity-filter-count"></span></button><label class="entity-sort">Ordenar<span class="sr-only"> registros</span><select data-entity-filter="sort">${entitySortOptions(state.sort)}</select></label></div><div class="admin-chips" role="group" aria-label="${quickLabel}">${config.quickOptions.map(([value,label])=>`<button class="filter-chip ${state[config.quickKey]===value?'active':''}" data-entity-quick="${value}" type="button">${label}</button>`).join('')}</div>${entityFilterPanel(type,config,state)}</div>`;
}

function sortEntityItems(items,state){
  const direction=state.sort==='za'?-1:1;const byName=(a,b)=>a.name.localeCompare(b.name,'es',{sensitivity:'base'})*direction;const byDate=(a,b)=>(new Date(a.created_at||0)-new Date(b.created_at||0))*(state.sort==='newest'?-1:1);
  return items.slice().sort(state.sort==='newest'||state.sort==='oldest'?byDate:byName);
}

function orderEntityItems(type,items,state){
  if(state.search){const query=cleanText(state.search);return sortEntityItems(items,state).sort((a,b)=>{const score=item=>{const name=cleanText(item.name);const slug=cleanText(item.slug);if(name===query)return 5;if(name.startsWith(query))return 4;if(name.includes(query))return 3;if(slug.includes(query))return 2;return 1;};return score(b)-score(a);});}
  if(type!=='categories'||state.kind!=='all'||state.parent)return sortEntityItems(items,state);
  const available=new Set(items.map(item=>item.id));const roots=sortEntityItems(items.filter(item=>!item.parent_id||!available.has(item.parent_id)),state);const ordered=[];const seen=new Set();
  roots.forEach(root=>{ordered.push(root);seen.add(root.id);sortEntityItems(items.filter(item=>item.parent_id===root.id),state).forEach(child=>{ordered.push(child);seen.add(child.id);});});
  ordered.push(...sortEntityItems(items.filter(item=>!seen.has(item.id)),state));return ordered;
}

function entityMatches(type,item,state){
  const parent=type==='categories'?categories.find(category=>category.id===item.parent_id):null;const searchable=[item.name,item.slug,parent?.name].filter(Boolean).join(' ');const words=cleanText(state.search).split(/\s+/).filter(Boolean);
  return words.every(word=>cleanText(searchable).includes(word))&&(state.status==='all'||(state.status==='active')===Boolean(item.active))&&(state.kind==='all'||(type==='categories'?(state.kind==='parent'?!item.parent_id:Boolean(item.parent_id)):item.type===state.kind))&&(!state.parent||item.parent_id===state.parent);
}

function entityAssetUrl(type,item){return type==='categories'?item?.image_url:item?.logo_url;}

function entityThumb(type,item){
  const url=entityAssetUrl(type,item);const initials=type==='categories'?categoryInitials(item.name):item.name.split(/\s+/).slice(0,2).map(word=>word[0]).join('').toUpperCase();
  const assetClass=type==='categories'?'entity-thumb--category':'entity-thumb--brand';
  return `<div class="data-row__thumb entity-thumb ${assetClass}">${url?`<img src="${escapeHtml(localAsset(url))}" alt="" loading="lazy" width="52" height="52">`:`<span aria-hidden="true">${escapeHtml(initials)}</span>`}</div>`;
}

function entityProductCount(type,item){return type==='categories'?products.filter(product=>product.product_categories.some(row=>row.category_id===item.id)).length:products.filter(product=>product.brand_id===item.id).length;}

function entityRows(type,items,{hierarchical=false,expandedParents=new Set(),childCounts=new Map()}={}){
  return `<div class="data-list entity-list ${hierarchical?'category-tree':''}">${items.map(item=>{const parent=type==='categories'?categories.find(category=>category.id===item.parent_id):null;const productCount=entityProductCount(type,item);const childCount=hierarchical&&!parent?Number(childCounts.get(item.id)||0):0;const expanded=childCount>0&&expandedParents.has(item.id);const detail=type==='categories'?(parent?`${parent.name} · slug: ${item.slug}`:`Categoría principal · slug: ${item.slug}`):`${entityKindLabel(type,item)} · slug: ${item.slug}`;const nameMarkup=hierarchical&&!parent&&childCount?`<button class="category-tree-toggle" data-toggle-category="${item.id}" type="button" aria-expanded="${expanded}" aria-label="${expanded?'Ocultar':'Mostrar'} ${childCount} ${childCount===1?'subcategoría':'subcategorías'} de ${escapeHtml(item.name)}"><span class="category-tree-toggle__chevron" aria-hidden="true">›</span><strong>${escapeHtml(item.name)}</strong><span class="category-tree-count">${childCount} ${childCount===1?'subcategoría':'subcategorías'}</span></button>`:`<strong>${parent?'<span class="entity-branch" aria-hidden="true">↳</span>':''}${escapeHtml(item.name)}</strong>${hierarchical&&!parent?'<span class="category-tree-count category-tree-count--empty">Sin subcategorías</span>':''}`;return `<article class="data-row entity-row ${parent?'entity-row--child':'entity-row--parent'} ${expanded?'entity-row--expanded':''}" data-entity-id="${item.id}" ${parent?`data-parent-id="${parent.id}"`:''}>${entityThumb(type,item)}<div class="data-row__main">${nameMarkup}<small>${escapeHtml(detail)}</small>${productCount?`<span class="entity-related-count">${productCount} ${productCount===1?'producto asociado':'productos asociados'}</span>`:''}</div><span class="status-pill status-pill--${item.active?'active':'hidden'}">${item.active?'Activo':'Inactivo'}</span><div class="data-row__actions"><button class="small-btn" data-edit data-edit-entity type="button">Editar</button><details class="action-menu"><summary aria-label="Más acciones para ${escapeHtml(item.name)}">⋮</summary><div class="action-menu__popover" role="menu"><button data-edit-entity type="button" role="menuitem">Editar</button>${productCount?'<button data-view-related type="button" role="menuitem">Ver productos</button>':''}<button data-delete-entity type="button" role="menuitem">Eliminar</button></div></details></div></article>`;}).join('')}</div>`;
}

function entityEmptyMarkup(config,state){
  if(!config.items.length)return `<div class="empty-state empty-state--admin entity-empty"><h3>No hay ${config.plural} todavía.</h3><p>Crea el primer registro para comenzar.</p><button class="btn btn--primary" data-create-entity type="button">+ ${config.button}</button></div>`;
  const query=state.search.trim();const title=query?`No encontramos ${config.plural} con “${escapeHtml(query)}”.`:`No encontramos ${config.plural} con estos filtros.`;return `<div class="empty-state empty-state--admin entity-empty"><h3>${title}</h3><p>Prueba otra búsqueda o vuelve a mostrar todos los registros.</p><button class="btn btn--ghost" data-clear-entities type="button">Limpiar búsqueda y filtros</button></div>`;
}

function updateEntityControls(config,state){
  $$('[data-entity-quick]').forEach(button=>button.classList.toggle('active',button.dataset.entityQuick===state[config.quickKey]));$$('[data-entity-filter]').forEach(select=>{select.value=state[select.dataset.entityFilter];});
  const count=(state.status!=='all'?1:0)+(state.kind!=='all'?1:0)+(state.parent?1:0);$('#entity-filter-count').textContent=count?`(${count})`:'';
}

function relatedProductParams(type,item){return type==='categories'?{category:item.id}:{brand:item.id};}

function showEntityDependency(type,item,dependencies,trigger=null){
  const config=getEntityConfig(type);const children=Number(dependencies.child_count||0);const related=Number(dependencies.product_count||0);const wrapper=document.createElement('div');wrapper.className='dependency-dialog';const messages=[];
  if(children)messages.push(`Esta categoría contiene ${children} ${children===1?'subcategoría':'subcategorías'}. Primero debes moverlas o eliminarlas.`);if(related)messages.push(type==='brands'?`La marca “${item.name}” está asociada a ${related} ${related===1?'producto':'productos'}.`:`No puedes eliminar “${item.name}” porque tiene ${related} ${related===1?'producto asociado':'productos asociados'}.`);
  wrapper.innerHTML=`${messages.map(message=>`<p>${escapeHtml(message)}</p>`).join('')}<p class="dependency-dialog__hint">Si solo quieres dejar de mostrar ${type==='categories'?'esta categoría':'esta marca'} en la tienda, puedes desactivarla en lugar de eliminarla.</p><div class="form-actions">${children?'<button class="btn btn--primary" data-view-children type="button">Ver subcategorías</button>':''}${related?`<button class="btn btn--primary" data-view-products type="button">Ver ${related} ${related===1?'producto':'productos'}</button>`:''}<button class="btn btn--ghost" data-close-dependency type="button">${children&&!related?'Entendido':'Cancelar'}</button></div>`;
  const modal=openModal({title:`No puedes eliminar esta ${config.singular} todavía`,content:wrapper,trigger});
  wrapper.querySelector('[data-close-dependency]').addEventListener('click',()=>modal.close());wrapper.querySelector('[data-view-children]')?.addEventListener('click',()=>{modal.close();navigateTo('categories',{parent:item.id});});wrapper.querySelector('[data-view-products]')?.addEventListener('click',()=>{modal.close();navigateTo('products',relatedProductParams(type,item));});
}

async function requestEntityDeletion(type,item,trigger){
  const config=getEntityConfig(type);const article='la';trigger.disabled=true;let dependencies;
  try{dependencies=await getCatalogEntityDependencies(type,item.id);}catch(error){console.error(error);toast(`No pudimos comprobar si ${article} ${config.singular} puede eliminarse. Intenta nuevamente.`,'error');trigger.disabled=false;return;}trigger.disabled=false;
  if(!dependencies?.exists){toast(`La ${config.singular} ya no existe.`,'error');return;}if(!dependencies.can_delete){showEntityDependency(type,item,dependencies,trigger);return;}
  const confirmed=await confirmAction(`¿Seguro que deseas eliminar “${item.name}”? Esta acción no se puede deshacer.`,`Eliminar ${config.singular}`,{confirmLabel:`Eliminar ${config.singular}`,trigger});if(!confirmed)return;
  setButtonLoading(trigger,true,'Eliminando…');try{const result=await deleteCatalogEntitySafely(type,item.id);if(!result?.deleted){setButtonLoading(trigger,false);if(result?.reason==='children'||result?.reason==='products')showEntityDependency(type,item,result,trigger);else toast(`No pudimos eliminar ${article} ${config.singular}. Intenta nuevamente.`,'error');return;}
    if(type==='categories')categories=categories.filter(entity=>entity.id!==item.id);else brands=brands.filter(entity=>entity.id!==item.id);renderEntities(type);toast(`${config.title.slice(0,-1)} eliminada correctamente.`);removeCatalogEntityAsset(type,entityAssetUrl(type,item)).catch(error=>console.warn('No se pudo limpiar el activo administrado:',error));
  }catch(error){console.error(error);setButtonLoading(trigger,false);toast(`No pudimos eliminar ${article} ${config.singular}. Intenta nuevamente.`,'error');}
}

function renderEntities(type){
  const config=getEntityConfig(type);const state=getEntityState(type);const expandedParents=new Set();const registeredWord=(config.items.length===1?'registrada':'registradas');$('#admin-content').innerHTML=heading('Organización',config.title,'Administra lo que los clientes usan para explorar.',`<button id="new-entity" class="btn btn--primary" type="button">+ ${config.button}</button>`)+`<section class="admin-panel entity-manager"><div class="admin-panel__head"><h2>${config.title}</h2><p>${config.items.length} ${config.items.length===1?config.singular:config.plural} ${registeredWord}</p></div>${entityToolbar(type,config,state)}<div id="entity-results" aria-live="polite"></div></section>`;
  const resultsRoot=$('#entity-results');const renderResults=()=>{const matching=config.items.filter(item=>entityMatches(type,item,state));let hierarchical=type==='categories'&&!state.search.trim()&&state.kind==='all'&&!state.parent;let visible;let pages;let meta;let rowOptions={};if(hierarchical){const roots=sortEntityItems(matching.filter(item=>!item.parent_id),state);if(!roots.length&&matching.length)hierarchical=false;else{const rootIds=new Set(roots.map(item=>item.id));const childCounts=new Map();const childrenByParent=new Map();matching.filter(item=>item.parent_id&&rootIds.has(item.parent_id)).forEach(item=>{if(!childrenByParent.has(item.parent_id))childrenByParent.set(item.parent_id,[]);childrenByParent.get(item.parent_id).push(item);});childrenByParent.forEach((children,parentId)=>{const ordered=sortEntityItems(children,state);childrenByParent.set(parentId,ordered);childCounts.set(parentId,ordered.length);});pages=Math.max(1,Math.ceil(roots.length/ENTITY_PAGE_SIZE));state.page=Math.min(state.page,pages);const pageRoots=roots.slice((state.page-1)*ENTITY_PAGE_SIZE,state.page*ENTITY_PAGE_SIZE);visible=pageRoots.flatMap(root=>[root,...(expandedParents.has(root.id)?childrenByParent.get(root.id)||[]:[])]);const childTotal=[...childCounts.values()].reduce((sum,count)=>sum+count,0);meta=`${roots.length} ${roots.length===1?'principal':'principales'} · ${childTotal} ${childTotal===1?'subcategoría':'subcategorías'}`;rowOptions={hierarchical:true,expandedParents,childCounts};}}
    if(!hierarchical){const filtered=orderEntityItems(type,matching,state);pages=Math.max(1,Math.ceil(filtered.length/ENTITY_PAGE_SIZE));state.page=Math.min(state.page,pages);visible=filtered.slice((state.page-1)*ENTITY_PAGE_SIZE,state.page*ENTITY_PAGE_SIZE);meta=`${filtered.length} ${filtered.length===1?'resultado':'resultados'}`;}
    resultsRoot.innerHTML=`<div class="results-meta entity-results-meta"><span>${meta}</span>${state.search||state.status!=='all'||state.kind!=='all'||state.parent||state.sort!=='az'?'<button data-clear-entities type="button">Limpiar</button>':''}</div>${visible.length?entityRows(type,visible,rowOptions):entityEmptyMarkup(config,state)}${paginationMarkup(state.page,pages)}`;bindPagination(resultsRoot,state,pages,renderResults);updateEntityControls(config,state);syncSectionUrl(type,state);};
  $('#new-entity').addEventListener('click',()=>openEntityForm(type));$('#entity-filters-button').addEventListener('click',event=>{const panel=$('#entity-filter-panel');panel.hidden=!panel.hidden;event.currentTarget.setAttribute('aria-expanded',String(!panel.hidden));});
  const search=debounce(value=>{state.search=value;state.page=1;renderResults();},200);$('#entity-search').addEventListener('input',event=>search(event.target.value));$$('[data-entity-quick]').forEach(button=>button.addEventListener('click',()=>{state[config.quickKey]=button.dataset.entityQuick;state.page=1;renderResults();}));$$('[data-entity-filter]').forEach(select=>select.addEventListener('change',event=>{state[event.target.dataset.entityFilter]=event.target.value;state.page=1;renderResults();}));
  resultsRoot.addEventListener('click',event=>{const clear=event.target.closest('[data-clear-entities]');if(clear){navigateTo(type);return;}const create=event.target.closest('[data-create-entity]');if(create){openEntityForm(type);return;}const row=event.target.closest('[data-entity-id]');if(!row)return;const item=config.items.find(entity=>entity.id===row.dataset.entityId);if(!item)return;const treeArea=event.target.closest('.data-row__thumb,.data-row__main');const toggle=event.target.closest('[data-toggle-category]')||(treeArea?row.querySelector('[data-toggle-category]'):null);if(toggle){if(expandedParents.has(item.id))expandedParents.delete(item.id);else expandedParents.add(item.id);renderResults();requestAnimationFrame(()=>resultsRoot.querySelector(`[data-toggle-category="${item.id}"]`)?.focus());return;}if(event.target.closest('[data-edit-entity]')){row.querySelector('.action-menu')?.removeAttribute('open');openEntityForm(type,item);}else if(event.target.closest('[data-delete-entity]')){row.querySelector('.action-menu')?.removeAttribute('open');requestEntityDeletion(type,item,event.target.closest('button'));}else if(event.target.closest('[data-view-related]'))navigateTo('products',relatedProductParams(type,item));});
  $('#entity-filter-panel').addEventListener('click',event=>{if(event.target.closest('[data-clear-entities]'))navigateTo(type);});renderResults();
}

function openEntityForm(type,item=null){
  const labels={categories:'categoría',brands:'marca'};
  const assetConfig={categories:{bucket:'category-images',folder:'categories',field:'image_url'},brands:{bucket:'brand-assets',folder:'brands',field:'logo_url'}}[type];
  const currentAsset=entityAssetUrl(type,item);const form=document.createElement('form');let previewUrl='';form.className='admin-form';
  const assetLabel=type==='categories'?'Foto de la categoría':'Logo de la marca';const assetContext=type==='categories'?'tarjetas de categorías':'tarjetas de marcas';const assetAlt=type==='categories'?'categoría':'marca';
  const assetMarkup=`<label class="entity-asset-field form-grid__full">${assetLabel} <span>Opcional</span><input name="asset" type="file" accept="image/jpeg,image/png,image/webp,image/svg+xml"><small>PNG, JPG, WebP o SVG, máximo 5 MB. La imagen se centrará y ajustará automáticamente sin deformarse.</small></label><div class="entity-asset-preview ${type==='categories'?'':'entity-asset-preview--logo'} form-grid__full" data-entity-asset-preview ${currentAsset?'':'hidden'}><img src="${currentAsset?escapeHtml(localAsset(currentAsset)):''}" alt="Vista previa de ${assetAlt}"><div><strong>Vista previa</strong><small>Así se ajustará en las ${assetContext}.</small>${currentAsset?`<label class="check-field"><input name="remove_asset" type="checkbox"> Quitar ${type==='categories'?'foto':'logo'} actual</label>`:''}</div></div>`;
  form.innerHTML=`<div class="form-grid"><label>Nombre<input name="name" value="${escapeHtml(item?.name||'')}" required></label><label>Slug<input name="slug" value="${escapeHtml(item?.slug||'')}" placeholder="Automático"></label>${type==='categories'?`<label>Categoría superior<select name="parent_id"><option value="">Ninguna</option>${categories.filter(c=>c.id!==item?.id&&!c.parent_id).map(c=>`<option value="${c.id}" ${item?.parent_id===c.id?'selected':''}>${escapeHtml(c.name)}</option>`).join('')}</select></label><label class="form-grid__full">Descripción<textarea name="description">${escapeHtml(item?.description||'')}</textarea></label>`:''}${assetMarkup}<label class="check-field"><input name="active" type="checkbox" ${item?.active!==false?'checked':''}> Visible y activo</label></div><div class="form-actions"><button class="btn btn--primary" type="submit">Guardar</button></div>`;
  const modal=openModal({title:`${item?'Editar':'Nueva'} ${labels[type]}`,content:form,onClose:()=>{if(previewUrl)URL.revokeObjectURL(previewUrl);}});
  form.elements.asset.addEventListener('change',()=>{const file=form.elements.asset.files[0];if(!file)return;if(previewUrl)URL.revokeObjectURL(previewUrl);previewUrl=URL.createObjectURL(file);const preview=form.querySelector('[data-entity-asset-preview]');preview.hidden=false;preview.querySelector('img').src=previewUrl;form.elements.remove_asset&&(form.elements.remove_asset.checked=false);});
  form.addEventListener('submit',async event=>{event.preventDefault();const button=event.submitter;const data=new FormData(form);const file=form.elements.asset?.files?.[0];let uploadedUrl='';if(file&&file.size>5242880){toast('La imagen debe pesar máximo 5 MB.','error');return;}setButtonLoading(button,true,'Guardando…');try{const values={name:data.get('name').trim(),slug:data.get('slug').trim()||slugify(data.get('name')),active:data.has('active')};if(type==='categories')Object.assign(values,{parent_id:data.get('parent_id')||null,description:data.get('description').trim()||null});if(file){uploadedUrl=await uploadImage(assetConfig.bucket,file,assetConfig.folder);values[assetConfig.field]=uploadedUrl;}else if(data.has('remove_asset'))values[assetConfig.field]=null;await saveRow(type,values,item?.id);await refreshData();modal.close();renderEntities(type);toast('Cambios guardados');if(currentAsset&&(uploadedUrl||data.has('remove_asset')))removeCatalogEntityAsset(type,currentAsset).catch(error=>console.warn('No se pudo limpiar la imagen anterior:',error));}catch(error){console.error(error);if(uploadedUrl)removeCatalogEntityAsset(type,uploadedUrl).catch(()=>{});toast('No pudimos guardar. Revisa que el nombre y slug no estén repetidos.','error');setButtonLoading(button,false);}});
}

const PROMO_STATUS={active:{label:'Activa'},scheduled:{label:'Programada'},inactive:{label:'Inactiva'},ended:{label:'Finalizada'},none:{label:'Sin promoción'}};

function promoDiscount(product){const base=Number(product.base_price);const promo=Number(product.promo_price);return base>0&&product.promo_price!=null?Math.max(0,Math.round((1-promo/base)*100)):0;}
function promoStatus(product){return getPromotionStatus(product);}
function promoStatusLabel(product){return PROMO_STATUS[promoStatus(product)]?.label||PROMO_STATUS.none.label;}
function promoDate(value,withTime=false){if(!value)return'—';return new Date(value).toLocaleDateString('es-CO',withTime?{day:'numeric',month:'short',hour:'numeric',minute:'2-digit'}:{day:'numeric',month:'short'});}
function promoValidity(product){
  const status=promoStatus(product);if(status==='none')return'Sin vigencia';
  if(status==='scheduled')return`Empieza ${promoDate(product.promo_start)}`;
  if(status==='ended')return`Finalizó ${promoDate(product.promo_end)}`;
  if(!product.promo_start&&!product.promo_end)return'Sin fecha límite';
  if(!product.promo_end)return product.promo_start?`Desde ${promoDate(product.promo_start)}`:'Sin fecha límite';
  if(!product.promo_start)return`Hasta ${promoDate(product.promo_end)}`;
  return`${promoDate(product.promo_start)} → ${promoDate(product.promo_end)}`;
}
function promoSoonLabel(product){if(promoStatus(product)!=='active'||!product.promo_end)return'';const days=Math.ceil((new Date(product.promo_end).getTime()-Date.now())/86400000);return days>=0&&days<=3?days===0?'Finaliza hoy':`Finaliza en ${days} ${days===1?'día':'días'}`:'';}
function promoHaystack(product){return cleanText([product.name,product.brands?.name,...product.product_categories.map(row=>row.categories?.name)].filter(Boolean).join(' '));}

function promoActionMenu(product){
  const status=promoStatus(product);const actions=['<button data-promo-preview type="button">Vista previa</button>'];
  if(status==='active')actions.push('<button data-promo-disable type="button">Desactivar</button>','<button data-promo-finish type="button">Finalizar ahora</button>');
  if(status==='scheduled')actions.push('<button data-promo-start-now type="button">Iniciar ahora</button>','<button data-promo-disable type="button">Desactivar</button>');
  if(status==='inactive')actions.push('<button data-promo-enable type="button">Activar</button>');
  if(status==='ended')actions.push('<button data-edit-promo type="button">Editar fechas</button>');
  if(status==='none')actions.push('<button data-edit-promo type="button">Crear promoción</button>');
  else actions.push('<button class="promo-menu-danger" data-remove-promo type="button">Eliminar promoción</button>');
  return `<details class="action-menu promo-action-menu"><summary aria-label="Más acciones para ${escapeHtml(product.name)}" aria-expanded="false">⋮</summary><div class="action-menu__popover">${actions.join('')}</div></details>`;
}

function promotionRow(product){
  const status=promoStatus(product);const discount=promoDiscount(product);const soon=promoSoonLabel(product);const configured=status!=='none';
  const price=configured?`<strong>${formatMoney(product.promo_price)}</strong><del>${formatMoney(product.base_price)}</del>`:`<strong>${formatMoney(product.base_price)}</strong><span>Precio normal</span>`;
  return `<article class="promotion-row" data-promo="${product.id}">
    <div class="promotion-cell promotion-product"><span class="promotion-thumb"><img src="${escapeHtml(productImage(product))}" alt="" loading="lazy" width="52" height="52" onerror="this.src='../assets/images/product-white.svg'"></span><span><strong>${escapeHtml(product.name)}</strong><small>${escapeHtml(product.brands?.name||'Producto')}</small></span></div>
    <div class="promotion-cell promotion-price" data-label="Promoción">${price}</div>
    <div class="promotion-cell promotion-discount" data-label="Descuento">${configured?`<strong>-${discount}%</strong><small>Ahorras ${formatMoney(Number(product.base_price)-Number(product.promo_price))}</small>`:'<span>—</span>'}</div>
    <div class="promotion-cell promotion-validity" data-label="Vigencia"><span>${promoValidity(product)}</span>${soon?`<small>${soon}</small>`:''}</div>
    <div class="promotion-cell promotion-state" data-label="Estado"><span class="status-pill status-pill--promo-${status}">${promoStatusLabel(product)}</span></div>
    <div class="promotion-cell promotion-actions"><button class="small-btn small-btn--primary" data-edit-promo type="button">${configured?'Editar':'Crear promoción'}</button>${promoActionMenu(product)}</div>
  </article>`;
}

function promoMetricsMarkup(counts,state){return `<div class="promo-metrics" aria-label="Resumen de promociones"><button class="${state.status==='active'?'active':''}" data-promo-metric="active" type="button"><strong>${counts.active}</strong><span>Activas</span></button><button class="${state.status==='scheduled'?'active':''}" data-promo-metric="scheduled" type="button"><strong>${counts.scheduled}</strong><span>Programadas</span></button><button class="${state.status==='ended'?'active':''}" data-promo-metric="ended" type="button"><strong>${counts.ended}</strong><span>Finalizadas</span></button></div>`;}

function renderPromotions(){
  const params=new URLSearchParams(location.search);const allowed=['all','active','scheduled','inactive','ended','none'];
  const state={search:params.get('search')||'',status:allowed.includes(params.get('status'))?params.get('status'):'all',category:params.get('category')||'',brand:params.get('brand')||'',minDiscount:params.get('minDiscount')||'',maxDiscount:params.get('maxDiscount')||'',sort:params.get('sort')||'recent',page:Math.max(1,Number(params.get('page'))||1)};
  $('#admin-content').innerHTML=heading('Precios especiales','Promociones','Crea, programa y administra las ofertas de tu catálogo.','<button id="new-promotion" class="btn btn--primary" type="button">+ Nueva promoción</button>')+`<section class="promotion-manager"><div id="promo-metrics-root"></div><div class="admin-panel promotion-panel"><div class="admin-toolbar admin-toolbar--sticky promo-toolbar"><div class="admin-search-wrap"><input id="promotion-search" class="admin-search" type="search" value="${escapeHtml(state.search)}" placeholder="Buscar producto o marca" aria-label="Buscar promociones"></div><button id="promotion-filters-button" class="toolbar-button" type="button" aria-expanded="false" aria-controls="promotion-filter-panel">Filtros <span id="promotion-filter-count"></span></button><label class="promo-sort-control"><span>Ordenar</span><select id="promotion-sort" aria-label="Ordenar promociones"><option value="recent">Más recientes</option><option value="az">A–Z</option><option value="discount-desc">Mayor descuento</option><option value="discount-asc">Menor descuento</option><option value="price-asc">Precio menor</option><option value="price-desc">Precio mayor</option><option value="ending">Finalizan primero</option></select></label><div class="admin-chips promo-status-chips" role="group" aria-label="Filtrar promociones por estado">${[['all','Todas'],['active','Activas'],['scheduled','Programadas'],['inactive','Inactivas'],['ended','Finalizadas'],['none','Sin promoción']].map(([value,label])=>`<button class="filter-chip ${state.status===value?'active':''}" data-promo-status="${value}" type="button">${label}</button>`).join('')}</div><div id="promotion-filter-panel" class="filter-panel" hidden>${selectFilter('promotion-category','Categoría',categories,state.category)}${selectFilter('promotion-brand','Marca',brands,state.brand)}<label>Descuento mínimo<input id="promotion-min-discount" type="number" min="0" max="100" value="${escapeHtml(state.minDiscount)}" placeholder="0%"></label><label>Descuento máximo<input id="promotion-max-discount" type="number" min="0" max="100" value="${escapeHtml(state.maxDiscount)}" placeholder="100%"></label><div class="filter-panel__wide"><button id="clear-promotion-filters" class="small-btn" type="button">Limpiar filtros</button></div></div></div><div id="promotion-results" aria-live="polite"></div></div></section>`;
  $('#promotion-sort').value=state.sort;
  const renderResults=()=>{
    const counts={active:0,scheduled:0,inactive:0,ended:0,none:0};products.forEach(product=>counts[promoStatus(product)]++);$('#promo-metrics-root').innerHTML=promoMetricsMarkup(counts,state);
    const query=cleanText(state.search);let filtered=products.filter(product=>{const status=promoStatus(product);const discount=promoDiscount(product);const statusMatch=state.status==='all'?status!=='none':status===state.status;return statusMatch&&(!query||promoHaystack(product).includes(query))&&(!state.category||product.product_categories.some(row=>row.category_id===state.category))&&(!state.brand||product.brand_id===state.brand)&&(state.minDiscount===''||discount>=Number(state.minDiscount))&&(state.maxDiscount===''||discount<=Number(state.maxDiscount));});
    const price=product=>Number(product.promo_price??product.base_price);const end=product=>product.promo_end?new Date(product.promo_end).getTime():Number.MAX_SAFE_INTEGER;
    filtered.sort((a,b)=>state.sort==='az'?a.name.localeCompare(b.name):state.sort==='discount-desc'?promoDiscount(b)-promoDiscount(a):state.sort==='discount-asc'?promoDiscount(a)-promoDiscount(b):state.sort==='price-asc'?price(a)-price(b):state.sort==='price-desc'?price(b)-price(a):state.sort==='ending'?end(a)-end(b):new Date(b.updated_at)-new Date(a.updated_at));
    const pages=Math.max(1,Math.ceil(filtered.length/PAGE_SIZE));state.page=Math.min(state.page,pages);const visible=filtered.slice((state.page-1)*PAGE_SIZE,state.page*PAGE_SIZE);const hasFilters=state.search||state.category||state.brand||state.minDiscount!==''||state.maxDiscount!==''||state.status!=='all';
    $('#promotion-results').innerHTML=`<div class="results-meta promo-results-meta"><span>${filtered.length} ${filtered.length===1?'resultado':'resultados'}</span>${hasFilters?'<button data-clear-promotions type="button">Limpiar</button>':''}</div>${visible.length?`<div class="promotion-table" role="table" aria-label="Promociones"><div class="promotion-table__head" role="row"><span>Producto</span><span>Promoción</span><span>Descuento</span><span>Vigencia</span><span>Estado</span><span>Acciones</span></div>${visible.map(promotionRow).join('')}</div>`:`<div class="empty-state empty-state--admin promotion-empty"><h3>${state.status==='scheduled'?'No hay promociones programadas':state.status==='none'?'No hay productos sin promoción':'No encontramos promociones'}</h3><p>${hasFilters?'Prueba otra búsqueda o limpia los filtros.':'Crea la primera oferta para empezar.'}</p>${!hasFilters?'<button class="btn btn--primary" data-create-first-promo type="button">+ Crear primera promoción</button>':''}</div>`}${paginationMarkup(state.page,pages)}`;
    bindPagination($('#promotion-results'),state,pages,renderResults);bindPromotionActions(renderResults);updatePromotionControls(state);syncSectionUrl('promotions',state);
    $$('[data-promo-metric]').forEach(button=>button.addEventListener('click',()=>{state.status=button.dataset.promoMetric;state.page=1;renderResults();}));
    $('[data-clear-promotions]')?.addEventListener('click',()=>navigateTo('promotions'));$('[data-create-first-promo]')?.addEventListener('click',event=>openNewPromotionPicker(event.currentTarget));
  };
  $('#new-promotion').addEventListener('click',event=>openNewPromotionPicker(event.currentTarget));$('#promotion-filters-button').addEventListener('click',event=>{const panel=$('#promotion-filter-panel');panel.hidden=!panel.hidden;event.currentTarget.setAttribute('aria-expanded',String(!panel.hidden));});
  const search=debounce(value=>{state.search=value;state.page=1;renderResults();},200);$('#promotion-search').addEventListener('input',event=>search(event.target.value));
  $$('[data-promo-status]').forEach(button=>button.addEventListener('click',()=>{state.status=button.dataset.promoStatus;state.page=1;renderResults();}));
  [['#promotion-category','category'],['#promotion-brand','brand'],['#promotion-min-discount','minDiscount'],['#promotion-max-discount','maxDiscount'],['#promotion-sort','sort']].forEach(([selector,key])=>$(selector).addEventListener('change',event=>{state[key]=event.target.value;state.page=1;renderResults();}));
  $('#clear-promotion-filters').addEventListener('click',()=>navigateTo('promotions'));renderResults();
}

function updatePromotionControls(state){
  $$('[data-promo-status]').forEach(button=>button.classList.toggle('active',button.dataset.promoStatus===state.status));$('#promotion-sort').value=state.sort;
  const count=['category','brand','minDiscount','maxDiscount'].filter(key=>state[key]!==''&&state[key]!=null).length;$('#promotion-filter-count').textContent=count?`(${count})`:'';
}

function openNewPromotionPicker(trigger=null){
  const wrapper=document.createElement('div');wrapper.className='promotion-picker';wrapper.innerHTML=`<label class="promotion-picker__search">Selecciona un producto<input type="search" placeholder="Buscar producto, marca o categoría" autocomplete="off" aria-label="Buscar producto para promocionar"></label><p class="promotion-picker__hint">Elige un producto existente. Aquí no se crean productos nuevos.</p><div class="promotion-picker__results" aria-live="polite"></div>`;
  const modal=openModal({title:'Nueva promoción',content:wrapper,className:'modal--promotion',trigger});const input=wrapper.querySelector('input');const results=wrapper.querySelector('.promotion-picker__results');
  const render=value=>{const query=cleanText(value);const words=query.split(' ').filter(Boolean);const matches=products.filter(product=>!words.length||words.every(word=>promoHaystack(product).includes(word))).sort((a,b)=>Number(a.promo_price!=null)-Number(b.promo_price!=null)||a.name.localeCompare(b.name)).slice(0,10);results.innerHTML=matches.length?matches.map(product=>`<article class="promotion-picker__item" data-picker-product="${product.id}"><img src="${escapeHtml(productImage(product))}" alt="" width="52" height="52" onerror="this.src='../assets/images/product-white.svg'"><span><strong>${escapeHtml(product.name)}</strong><small>${escapeHtml(product.brands?.name||'Producto')} · ${formatMoney(product.base_price)}</small>${product.promo_price!=null?'<em>Este producto ya tiene una promoción.</em>':''}</span><button class="small-btn ${product.promo_price==null?'small-btn--primary':''}" type="button">${product.promo_price!=null?'Editar promoción':'Seleccionar'}</button></article>`).join(''):emptyMarkup('No encontramos productos','Prueba con otro nombre, marca o categoría.');};
  const run=debounce(value=>render(value),200);input.addEventListener('input',event=>run(event.target.value));results.addEventListener('click',event=>{const row=event.target.closest('[data-picker-product]');if(!row)return;const product=products.find(item=>item.id===row.dataset.pickerProduct);modal.close();queueMicrotask(()=>openPromoForm(product,trigger));});render('');requestAnimationFrame(()=>input.focus());
}

function promoPreviewMarkup(product,promoPrice){const discount=Number.isFinite(promoPrice)&&promoPrice<Number(product.base_price)?Math.round((1-promoPrice/Number(product.base_price))*100):0;return `<article class="promotion-preview"><div class="promotion-preview__media"><img src="${escapeHtml(productImage(product))}" alt="" onerror="this.src='../assets/images/product-white.svg'"><span>${discount?`-${discount}%`:'Vista previa'}</span></div><div><small>${escapeHtml(product.brands?.name||'Bodega Mayorista F.C.')}</small><strong>${escapeHtml(product.name)}</strong><p><b>${Number.isFinite(promoPrice)?formatMoney(promoPrice):'—'}</b><del>${formatMoney(product.base_price)}</del></p></div></article>`;}

function openPromoForm(product,trigger=null){
  const creating=product.promo_price==null;const form=document.createElement('form');form.className='admin-form promotion-form';form.noValidate=true;form.innerHTML=`<div class="promotion-form__product"><img src="${escapeHtml(productImage(product))}" alt="" width="64" height="64" onerror="this.src='../assets/images/product-white.svg'"><span><small>Producto seleccionado</small><strong>${escapeHtml(product.name)}</strong><em>Precio normal: ${formatMoney(product.base_price)}</em></span></div><div class="promotion-form__fields"><label>Precio promocional <span>Obligatorio</span><input name="promo_price" type="number" min="0" max="${Math.max(0,Number(product.base_price)-.01)}" step="100" inputmode="numeric" value="${product.promo_price??''}" required><small data-promo-calculation>Ingresa un precio menor al normal.</small></label><label>Inicio <span>Opcional</span><span class="input-with-action"><input name="promo_start" type="datetime-local" value="${toLocalInput(product.promo_start)}"><button data-start-now type="button">Iniciar ahora</button></span></label><label>Finalización <span>Opcional</span><input name="promo_end" type="datetime-local" value="${toLocalInput(product.promo_end)}"></label><label class="promotion-toggle"><input name="promo_enabled" type="checkbox" ${product.promo_enabled!==false?'checked':''}><span aria-hidden="true"></span><strong>Promoción habilitada<small>Puede pausarla sin perder la configuración.</small></strong></label></div><div data-promo-form-error class="promotion-form__error" role="alert" hidden></div><section class="promotion-form__preview"><h3>Vista previa</h3><div data-promo-preview></div></section><div class="promotion-form__footer"><button class="btn btn--ghost" data-cancel-promo type="button">Cancelar</button><button class="btn btn--primary" type="submit">${creating?'Crear promoción':'Guardar cambios'}</button></div>`;
  const modal=openModal({title:creating?'Crear promoción':'Editar promoción',content:form,className:'modal--promotion',trigger});const priceInput=form.elements.promo_price;const calculation=form.querySelector('[data-promo-calculation]');const preview=form.querySelector('[data-promo-preview]');const errorRoot=form.querySelector('[data-promo-form-error]');
  const updatePreview=()=>{const value=priceInput.value===''?NaN:Number(priceInput.value);const valid=Number.isFinite(value)&&value>=0&&value<Number(product.base_price);const discount=valid?Math.round((1-value/Number(product.base_price))*100):0;calculation.textContent=valid?`${discount}% de descuento · El cliente ahorra ${formatMoney(Number(product.base_price)-value)}.`:'Ingresa un precio menor al precio normal.';calculation.classList.toggle('valid',valid);preview.innerHTML=promoPreviewMarkup(product,valid?value:NaN);};
  priceInput.addEventListener('input',updatePreview);form.querySelector('[data-start-now]').addEventListener('click',()=>{form.elements.promo_start.value=toLocalInput(new Date());form.elements.promo_start.focus();});form.querySelector('[data-cancel-promo]').addEventListener('click',()=>modal.close());
  form.addEventListener('submit',async event=>{event.preventDefault();const button=event.submitter;const price=Number(priceInput.value);const start=form.elements.promo_start.value?new Date(form.elements.promo_start.value):null;const end=form.elements.promo_end.value?new Date(form.elements.promo_end.value):null;let message='';if(priceInput.value===''||!Number.isFinite(price)||price<0)message='Ingresa un precio promocional válido.';else if(price>=Number(product.base_price))message='El precio promocional debe ser menor al precio normal.';else if((start&&Number.isNaN(start.getTime()))||(end&&Number.isNaN(end.getTime())))message='Revisa las fechas de la promoción.';else if(start&&end&&end<=start)message='La fecha de finalización debe ser posterior al inicio.';if(message){errorRoot.textContent=message;errorRoot.hidden=false;return;}errorRoot.hidden=true;setButtonLoading(button,true,'Guardando…');const values={promo_price:price,promo_start:start?start.toISOString():null,promo_end:end?end.toISOString():null,promo_enabled:form.elements.promo_enabled.checked};try{const saved=await saveRow('products',values,product.id);Object.assign(product,saved,values,{updated_at:saved?.updated_at||new Date().toISOString()});modal.close();renderPromotions();requestAnimationFrame(()=>document.querySelector(`[data-promo="${CSS.escape(product.id)}"] [data-edit-promo]`)?.focus());toast(creating?'Promoción creada.':'Promoción actualizada.');}catch(error){console.error(error);toast('No pudimos guardar la promoción. Revisa los datos e intenta nuevamente.','error');setButtonLoading(button,false);}});updatePreview();
}

async function savePromotionChange(product,values,success,button,render){
  setButtonLoading(button,true,'Guardando…');try{const saved=await saveRow('products',values,product.id);Object.assign(product,saved,values,{updated_at:saved?.updated_at||new Date().toISOString()});render();toast(success);}catch(error){console.error(error);setButtonLoading(button,false);toast('No pudimos actualizar la promoción. Intenta nuevamente.','error');}
}

async function removePromotion(product,button,render){const confirmed=await confirmAction(`Se eliminará la oferta de ${product.name}. El producto continuará disponible con su precio normal.`,'Eliminar promoción',{confirmLabel:'Eliminar promoción',trigger:button});if(!confirmed)return;await savePromotionChange(product,{promo_price:null,promo_start:null,promo_end:null,promo_enabled:true},'Promoción eliminada.',button,render);}

function bindPromotionActions(render){
  $$('[data-promo]').forEach(row=>{const product=products.find(item=>item.id===row.dataset.promo);if(!product)return;row.querySelectorAll('[data-edit-promo]').forEach(button=>button.addEventListener('click',()=>openPromoForm(product,button)));row.querySelector('[data-promo-preview]')?.addEventListener('click',()=>window.open(`../producto.html?slug=${encodeURIComponent(product.slug)}`,'_blank','noopener'));row.querySelector('[data-remove-promo]')?.addEventListener('click',event=>removePromotion(product,event.currentTarget,render));row.querySelector('[data-promo-disable]')?.addEventListener('click',event=>savePromotionChange(product,{promo_enabled:false},'Promoción desactivada.',event.currentTarget,render));row.querySelector('[data-promo-enable]')?.addEventListener('click',event=>{if(product.promo_end&&new Date(product.promo_end)<=new Date()){toast('Esta promoción ya finalizó. Edita sus fechas para activarla.','error');return;}savePromotionChange(product,{promo_enabled:true},product.promo_start&&new Date(product.promo_start)>new Date()?'Promoción programada.':'Promoción activada.',event.currentTarget,render);});row.querySelector('[data-promo-start-now]')?.addEventListener('click',event=>{if(product.promo_end&&new Date(product.promo_end)<=new Date()){toast('Esta promoción ya finalizó. Edita sus fechas.','error');return;}savePromotionChange(product,{promo_start:new Date().toISOString(),promo_enabled:true},'Promoción iniciada.',event.currentTarget,render);});row.querySelector('[data-promo-finish]')?.addEventListener('click',event=>savePromotionChange(product,{promo_end:new Date().toISOString()},'Promoción finalizada.',event.currentTarget,render));});
}

function passwordErrorMessage(error){
  const detail=`${error?.code||''} ${error?.message||''}`.toLowerCase();
  if(detail.includes('current_password')||detail.includes('current password')||detail.includes('invalid credentials')||detail.includes('invalid login'))return'La contraseña actual no es correcta.';
  if(detail.includes('same_password')||detail.includes('same password')||detail.includes('different from the old'))return'La nueva contraseña debe ser diferente de la actual.';
  if(detail.includes('weak_password')||detail.includes('weak password')||detail.includes('password should')||detail.includes('password must'))return'La nueva contraseña no cumple los requisitos de seguridad.';
  if(detail.includes('rate')||detail.includes('too many'))return'Has realizado varios intentos. Espera unos minutos y vuelve a intentarlo.';
  if(detail.includes('session')||detail.includes('jwt')||detail.includes('token'))return'Tu sesión venció. Inicia sesión nuevamente antes de cambiar la contraseña.';
  return'No pudimos actualizar la contraseña. Revisa los datos e intenta nuevamente.';
}

function openPasswordChangeModal(trigger){
  const form=document.createElement('form');form.className='admin-form password-change-form';form.noValidate=true;
  form.innerHTML=`<p class="password-change-intro">Por seguridad, confirma tu contraseña actual y crea una nueva.</p><p class="password-form-error" data-password-error role="alert" tabindex="-1" hidden></p><div class="password-fields"><label><span>Contraseña actual</span><span class="password-input"><input name="current_password" type="password" autocomplete="current-password" required aria-describedby="password-current-help"><button type="button" data-toggle-password aria-label="Mostrar contraseña actual" aria-pressed="false">Mostrar</button></span><small id="password-current-help">Se comprobará de forma segura con tu cuenta de Supabase.</small></label><label><span>Nueva contraseña</span><span class="password-input"><input name="new_password" type="password" autocomplete="new-password" minlength="8" required aria-describedby="password-requirements"><button type="button" data-toggle-password aria-label="Mostrar nueva contraseña" aria-pressed="false">Mostrar</button></span></label><label><span>Confirmar nueva contraseña</span><span class="password-input"><input name="confirm_password" type="password" autocomplete="new-password" minlength="8" required><button type="button" data-toggle-password aria-label="Mostrar confirmación de contraseña" aria-pressed="false">Mostrar</button></span></label></div><div id="password-requirements" class="password-requirements" aria-live="polite"><strong>La nueva contraseña debe tener:</strong><ul><li data-password-rule="length">Mínimo 8 caracteres</li><li data-password-rule="letter">Al menos una letra</li><li data-password-rule="number">Al menos un número</li><li data-password-rule="different">Ser diferente de la actual</li></ul></div><div class="password-change-actions"><button class="btn btn--ghost" data-cancel-password type="button">Cancelar</button><button class="btn btn--primary" type="submit">Continuar</button></div>`;
  const modal=openModal({title:'Cambiar contraseña',content:form,className:'modal--password',trigger,description:'Confirma tu contraseña actual antes de establecer una nueva.'});const errorRoot=form.querySelector('[data-password-error]');const currentInput=form.elements.current_password;const newInput=form.elements.new_password;const confirmInput=form.elements.confirm_password;
  const passwordState=()=>({length:newInput.value.length>=8,letter:/[a-záéíóúñ]/i.test(newInput.value),number:/\d/.test(newInput.value),different:Boolean(newInput.value)&&newInput.value!==currentInput.value});
  const updateRequirements=()=>{const state=passwordState();Object.entries(state).forEach(([rule,valid])=>form.querySelector(`[data-password-rule="${rule}"]`)?.classList.toggle('is-valid',valid));if(confirmInput.value)confirmInput.setAttribute('aria-invalid',String(confirmInput.value!==newInput.value));else confirmInput.removeAttribute('aria-invalid');};
  const showError=(message,input)=>{errorRoot.textContent=message;errorRoot.hidden=false;if(input){input.setAttribute('aria-invalid','true');input.focus();}else errorRoot.focus();};
  form.querySelectorAll('[data-toggle-password]').forEach(button=>button.addEventListener('click',()=>{const input=button.previousElementSibling;const show=input.type==='password';input.type=show?'text':'password';button.textContent=show?'Ocultar':'Mostrar';button.setAttribute('aria-pressed',String(show));button.setAttribute('aria-label',`${show?'Ocultar':'Mostrar'} ${input.name==='current_password'?'contraseña actual':input.name==='new_password'?'nueva contraseña':'confirmación de contraseña'}`);input.focus();}));
  [currentInput,newInput,confirmInput].forEach(input=>input.addEventListener('input',()=>{input.removeAttribute('aria-invalid');errorRoot.hidden=true;updateRequirements();}));
  form.querySelector('[data-cancel-password]').addEventListener('click',()=>modal.close());
  form.addEventListener('submit',async event=>{event.preventDefault();errorRoot.hidden=true;[currentInput,newInput,confirmInput].forEach(input=>input.removeAttribute('aria-invalid'));const state=passwordState();if(!currentInput.value){showError('Escribe tu contraseña actual.',currentInput);return;}if(!state.length||!state.letter||!state.number){showError('La nueva contraseña debe tener mínimo 8 caracteres, una letra y un número.',newInput);return;}if(!state.different){showError('La nueva contraseña debe ser diferente de la actual.',newInput);return;}if(newInput.value!==confirmInput.value){showError('Las nuevas contraseñas no coinciden.',confirmInput);return;}const button=event.submitter||form.querySelector('[type="submit"]');const confirmed=await confirmAction('Se cambiará la contraseña de acceso de esta cuenta administradora.','Confirmar cambio de contraseña',{confirmLabel:'Cambiar contraseña',trigger:button,tone:'primary'});if(!confirmed)return;setButtonLoading(button,true,'Actualizando…');try{const{data,error}=await supabase.auth.updateUser({password:newInput.value,current_password:currentInput.value});if(error)throw error;if(data?.user&&adminSession)adminSession={...adminSession,user:data.user};currentInput.value='';newInput.value='';confirmInput.value='';modal.close();toast('Contraseña actualizada correctamente.');}catch(error){console.error('No se pudo actualizar la contraseña:',error);setButtonLoading(button,false);const errorDetail=`${error?.code||''} ${error?.message||''}`.toLowerCase();const errorInput=errorDetail.includes('current_password')||errorDetail.includes('current password')||errorDetail.includes('invalid credentials')||errorDetail.includes('invalid login')?currentInput:newInput;showError(passwordErrorMessage(error),errorInput);}});
  requestAnimationFrame(()=>currentInput.focus());
}

function announcementMessageRow(message,index,total,onChange){
  const row=document.createElement('article');row.className='announcement-message';row.dataset.messageId=message.id;
  const head=document.createElement('div');head.className='announcement-message__head';
  const position=document.createElement('strong');position.textContent=`Mensaje ${index+1}`;
  const state=document.createElement('span');state.textContent=message.enabled?'Activo':'Inactivo';state.className=`status-pill status-pill--${message.enabled?'active':'hidden'}`;
  head.append(position,state);
  const label=document.createElement('label');label.textContent='Texto del mensaje';
  const input=document.createElement('input');input.type='text';input.maxLength=ANNOUNCEMENT_TEXT_LIMIT;input.value=message.text;input.required=true;input.dataset.messageText=message.id;input.setAttribute('aria-describedby',`announcement-count-${message.id}`);
  const counter=document.createElement('small');counter.id=`announcement-count-${message.id}`;counter.className='announcement-character-count';counter.textContent=`${message.text.length}/${ANNOUNCEMENT_TEXT_LIMIT} caracteres`;
  input.addEventListener('input',()=>{message.text=input.value;counter.textContent=`${input.value.length}/${ANNOUNCEMENT_TEXT_LIMIT} caracteres`;input.removeAttribute('aria-invalid');onChange();});
  label.append(input,counter);
  const actions=document.createElement('div');actions.className='announcement-message__actions';
  const toggleLabel=document.createElement('label');toggleLabel.className='announcement-item-toggle';
  const checkbox=document.createElement('input');checkbox.type='checkbox';checkbox.checked=message.enabled;checkbox.setAttribute('aria-label',`Activar mensaje ${index+1}`);
  const toggleTrack=document.createElement('span');toggleTrack.setAttribute('aria-hidden','true');
  const toggleText=document.createElement('strong');toggleText.textContent=message.enabled?'Activo':'Inactivo';
  checkbox.addEventListener('change',()=>{message.enabled=checkbox.checked;toggleText.textContent=message.enabled?'Activo':'Inactivo';state.textContent=toggleText.textContent;state.className=`status-pill status-pill--${message.enabled?'active':'hidden'}`;onChange();});
  toggleLabel.append(checkbox,toggleTrack,toggleText);
  const order=document.createElement('div');order.className='announcement-order';
  const up=document.createElement('button');up.type='button';up.textContent='↑';up.disabled=index===0;up.title='Subir mensaje';up.setAttribute('aria-label',`Subir mensaje ${index+1}`);up.addEventListener('click',()=>onChange({move:index,direction:-1}));
  const down=document.createElement('button');down.type='button';down.textContent='↓';down.disabled=index===total-1;down.title='Bajar mensaje';down.setAttribute('aria-label',`Bajar mensaje ${index+1}`);down.addEventListener('click',()=>onChange({move:index,direction:1}));
  order.append(up,down);
  const remove=document.createElement('button');remove.type='button';remove.className='small-btn small-btn--danger';remove.textContent='Eliminar';remove.setAttribute('aria-label',`Eliminar mensaje ${index+1}`);remove.addEventListener('click',()=>onChange({remove:index}));
  actions.append(toggleLabel,order,remove);row.append(head,label,actions);return row;
}

